// Vertiefung für die ausführliche Theorie (Pro): warum die Regeln gelten, weitere durchgerechnete Beispiele, Sonderfälle.
// Eigene Texte. Die Abschnitte werden in theorie.js vor dem letzten Abschnitt des Kapitels eingefügt.
import { tex } from './ui.js';

const D = (s) => `<div class="t-formel">${tex(s, true)}</div>`;
const t = (s) => tex(s);

export const MEHR = {
  'a-grund': [
    ['Genauer hingeschaut: Woher die binomische Formel kommt', `<p>Sie ist kein Zaubertrick, sondern nur sauberes Ausmultiplizieren: jedes Glied der ersten Klammer mal jedes Glied der zweiten.</p>${D('(a+b)^2=(a+b)(a+b)=a^2+ab+ba+b^2')}<p>Die beiden mittleren Glieder sind gleich und ergeben zusammen ${t('2ab')}. Anschaulich: Ein Quadrat mit der Seitenlänge ${t('a+b')} besteht aus zwei Quadraten (${t('a^2')} und ${t('b^2')}) und zwei gleichen Rechtecken (${t('a\\cdot b')}).</p>`],
    ['Beispiel 2: Quadratische Gleichung mit Vorfaktor', `${D('2x^2-4x-6=0')}<p>Die pq-Formel verlangt eine 1 vor ${t('x^2')}. Also zuerst durch 2 teilen: ${t('x^2-2x-3=0')}. Mit ${t('p=-2')} und ${t('q=-3')}:</p>${D('x=1\\pm\\sqrt{1+3}=1\\pm 2')}<p>Lösungen: ${t('x_1=3')} und ${t('x_2=-1')}. Probe mit 3: ${t('2\\cdot 9-12-6=0')}.</p>`],
    ['Beispiel 3: Bruch kürzen', `${D('\\frac{x^2-9}{x+3}=\\frac{(x-3)(x+3)}{x+3}=x-3')}<p>Gekürzt wird nur, was als <b>Faktor</b> im ganzen Zähler und im ganzen Nenner steht – deshalb erst mit der dritten binomischen Formel zerlegen. Das Ergebnis gilt für alle ${t('x')} außer ${t('x=-3')}, denn dort wäre der Nenner null.</p>`],
    ['Beispiel 4: Wurzeln als Potenzen schreiben', `${D('\\sqrt x\\cdot x^2=x^{1/2}\\cdot x^{2}=x^{5/2}\\qquad\\frac{1}{x^3}=x^{-3}')}<p>Diese Schreibweise ist die Voraussetzung dafür, später mit der Potenzregel ableiten und integrieren zu können.</p>`],
    ['Beispiel 5: Gleichung mit Brüchen', `${D('\\frac{x+1}{2}=\\frac{2x-1}{3}')}<p>Beide Seiten mit dem gemeinsamen Nenner 6 malnehmen – dann sind die Brüche weg: ${t('3\\,(x+1)=2\\,(2x-1)')}. Ausmultiplizieren: ${t('3x+3=4x-2')}, also ${t('x=5')}. Probe: links ${t('\\tfrac62=3')}, rechts ${t('\\tfrac93=3')}.</p>`],
    ['Sonderfälle', `<ul><li><b>Wurzel wird null:</b> ${t('x^2-6x+9=0')} hat nur die eine Lösung ${t('x=3')} (doppelte Lösung) – der Graph berührt die x-Achse.</li><li><b>Wurzel wird negativ:</b> ${t('x^2+2x+5=0')} hat keine Lösung – der Graph liegt ganz über der Achse.</li><li><b>Reines Quadrat:</b> ${t('x^2=16')} hat <b>zwei</b> Lösungen, ${t('4')} und ${t('-4')}.</li><li><b>${t('x')} fällt heraus:</b> Bleibt ${t('0=0')}, ist jede Zahl Lösung. Bleibt ${t('0=5')}, gibt es keine.</li></ul>`],
  ],
  formen: [
    ['Genauer hingeschaut: Von der Normalform zur Scheitelform', `<p>Steht die Parabel als ${t('x^2+px+q')} da, liefert die <b>quadratische Ergänzung</b> den Scheitel: die Hälfte von ${t('p')} quadrieren, addieren und gleich wieder abziehen.</p>${D('x^2-6x+5=(x^2-6x+9)-9+5=(x-3)^2-4')}<p>Der Scheitel ist ${t('S(3\\mid -4)')}. Genau diese Umformung steckt übrigens hinter der pq-Formel.</p>`],
    ['Beispiel 2: Gerade durch zwei Punkte', `<p>Gesucht ist die Gerade durch ${t('P(1\\mid 2)')} und ${t('Q(4\\mid 8)')}.</p>${D('m=\\frac{8-2}{4-1}=2')}<p>Einen Punkt einsetzen: ${t('2=2\\cdot 1+b')}, also ${t('b=0')}. Ergebnis: ${t('y=2x')}. Probe mit ${t('Q')}: ${t('2\\cdot 4=8')}.</p>`],
    ['Beispiel 3: Sinusfunktion vom Graphen ablesen', `<p>Ein Graph schwankt zwischen dem höchsten Wert 5 und dem tiefsten Wert 1 und wiederholt sich alle 4 Einheiten. Er startet bei ${t('x=0')} in der Mittellage nach oben.</p><p>Mittellage: ${t('d=\\tfrac{5+1}{2}=3')}. Amplitude: ${t('a=5-3=2')}. Aus der Periode: ${t('b=\\tfrac{2\\pi}{4}=\\tfrac{\\pi}{2}')}.</p>${D('f(x)=2\\sin\\Bigl(\\frac{\\pi}{2}\\,x\\Bigr)+3')}`],
    ['Sonderfälle', `<ul><li><b>Negatives ${t('a')}:</b> Der Graph wird an der x-Achse gespiegelt – die Parabel öffnet nach unten, der Sinus startet nach unten.</li><li><b>${t('f(-x)')}:</b> Spiegelung an der y-Achse.</li><li><b>Steigung null:</b> Die Gerade ${t('y=b')} verläuft waagerecht.</li><li><b>Senkrechte Gerade:</b> ${t('x=3')} ist keine Funktion – zu einem ${t('x')} gehören unendlich viele ${t('y')}.</li><li><b>Startet der Sinus im Hochpunkt</b>, passt der Kosinus besser: gleiche Form, nur verschoben.</li></ul>`],
  ],
  steigung: [
    ['Genauer hingeschaut: Die Ableitung als Funktion', `<p>Rechnet man den Grenzwert nicht für eine feste Zahl, sondern für ein beliebiges ${t('x')}, erhält man gleich die Steigung an <b>jeder</b> Stelle:</p>${D('\\frac{(x+h)^2-x^2}{h}=\\frac{2xh+h^2}{h}=2x+h')}<p>Für ${t('h\\to 0')} bleibt ${t('2x')}. Das ist die Ableitungsfunktion von ${t('x^2')} – und genau das, was die Potenzregel später ohne Rechnung liefert.</p>`],
    ['Beispiel 2: Mittlere und momentane Änderung', `<p>Ein Stein fällt: ${t('s(t)=5t^2')} (Weg in Metern, Zeit in Sekunden).</p><p><b>Mittlere</b> Geschwindigkeit zwischen ${t('t=1')} und ${t('t=2')}: ${t('\\tfrac{s(2)-s(1)}{2-1}=\\tfrac{20-5}{1}=15')} m/s. Das ist die Steigung der Sekante.</p><p><b>Momentane</b> Geschwindigkeit bei ${t('t=2')}: ${t("s'(t)=10t")}, also ${t("s'(2)=20")} m/s. Das ist die Steigung der Tangente – das, was der Tacho in diesem Augenblick anzeigen würde.</p>`],
    ['Beispiel 3: Steigungswinkel', `${D("\\tan\\alpha=f'(x_0)")}<p>Die Steigung ist der Tangens des Winkels gegen die Waagerechte. Für ${t('f(x)=x^2')} an der Stelle ${t('x_0=0{,}5')} ist ${t("f'(0{,}5)=1")}, also ${t('\\alpha=45^\\circ')}. Eine Steigung von 100 % bedeutet also 45° – nicht senkrecht.</p>`],
    ['Sonderfälle', `<ul><li><b>Knick:</b> ${t('f(x)=|x|')} hat bei ${t('x=0')} links die Steigung ${t('-1')} und rechts ${t('+1')}. Eine eindeutige Tangente gibt es nicht – die Funktion ist dort nicht ableitbar.</li><li><b>Senkrechte Tangente:</b> ${t('\\sqrt x')} wird bei ${t('x=0')} unendlich steil; auch dort existiert keine Ableitung.</li><li><b>Waagerechte Tangente:</b> ${t("f'(x_0)=0")} – ein Kandidat für einen Extrempunkt.</li><li><b>Sprung:</b> Wo der Graph abreißt, gibt es keine Tangente.</li></ul>`],
  ],
  zeichnen: [
    ['Genauer hingeschaut: Was die Krümmung verrät', `<p>Ist der Graph von ${t('f')} wie eine Schüssel nach oben offen (Linkskurve), wird er nach rechts hin immer steiler: ${t("f'")} <b>steigt</b>. In einer Rechtskurve <b>fällt</b> ${t("f'")}. Am Wendepunkt wechselt die Krümmung – dort dreht ${t("f'")} um und hat selbst einen Hoch- oder Tiefpunkt.</p>`],
    ['Beispiel 2: Skizze nach Beschreibung', `<p>${t('f')} hat einen Hochpunkt bei ${t('x=-1')}, einen Tiefpunkt bei ${t('x=3')} und dazwischen einen Wendepunkt bei ${t('x=1')}.</p><ul><li>${t("f'")} hat Nullstellen bei ${t('-1')} und ${t('3')}.</li><li>Zwischen ihnen fällt ${t('f')}: ${t("f'")} liegt unter der Achse. Außerhalb steigt ${t('f')}: ${t("f'")} liegt darüber.</li><li>Bei ${t('x=1')} ist ${t('f')} am steilsten fallend: ${t("f'")} hat dort seinen Tiefpunkt.</li></ul><p>Ergebnis: eine nach oben offene Parabel mit Scheitel bei ${t('x=1')}.</p>`],
    ['Beispiel 3: Der Rückweg', `<p>Gegeben ist ${t("f'(x)=2x-4")}. Links von ${t('x=2')} ist ${t("f'")} negativ, rechts positiv: ${t('f')} fällt erst und steigt dann, hat also bei ${t('x=2')} einen Tiefpunkt. Passende Funktionen sind ${t('f(x)=x^2-4x+c')} – für jedes ${t('c')} eine, alle gleich geformt und nur in der Höhe verschoben.</p>`],
    ['Sonderfälle', `<ul><li><b>Sattelpunkt:</b> ${t("f'")} berührt die x-Achse, ohne sie zu kreuzen.</li><li><b>Gerade:</b> Die Steigung ist überall gleich – ${t("f'")} ist eine waagerechte Linie.</li><li><b>Konstante Funktion:</b> ${t("f'")} liegt auf der x-Achse.</li><li><b>Knick in ${t('f')}:</b> ${t("f'")} macht an dieser Stelle einen Sprung.</li></ul>`],
  ],
  regeln: [
    ['Genauer hingeschaut: Warum es eine Produktregel braucht', `<p>Man könnte meinen, ein Produkt leite man ab, indem man beide Faktoren einzeln ableitet. Ein einfacher Test zeigt, dass das nicht stimmt: ${t('x\\cdot x=x^2')} hat die Ableitung ${t('2x')}. Einzeln abgeleitet käme ${t('1\\cdot 1=1')} heraus – falsch. Die Produktregel liefert ${t('1\\cdot x+x\\cdot 1=2x')}.</p><p>Der Grund: Wenn beide Faktoren gleichzeitig wachsen, ändert sich das Produkt durch <b>beide</b> Zuwächse.</p>`],
    ['Beispiel 2: Kettenregel mit der e-Funktion', `${D("f(x)=e^{-x^2}\\qquad f'(x)=-2x\\cdot e^{-x^2}")}<p>Außen steht ${t('e^{\\dots}')}, das beim Ableiten bleibt, wie es ist. Innen steht ${t('-x^2')} mit der Ableitung ${t('-2x')}.</p>`],
    ['Beispiel 3: Produkt- und Kettenregel zusammen', `${D('f(x)=x^2\\cdot e^{3x}')}<p>${t('u=x^2')} mit ${t("u'=2x")}; ${t('v=e^{3x}')} mit ${t("v'=3e^{3x}")} (Kettenregel).</p>${D("f'(x)=2x\\,e^{3x}+x^2\\cdot 3e^{3x}=x\\,(2+3x)\\,e^{3x}")}<p>Das Ausklammern am Ende lohnt sich: Für die Nullstellen von ${t("f'")} sieht man sofort ${t('x=0')} und ${t('x=-\\tfrac23')}.</p>`],
    ['Beispiel 4: Wurzel und Bruch', `${D('f(x)=\\sqrt x+\\frac{1}{x^2}=x^{1/2}+x^{-2}')}${D("f'(x)=\\tfrac12\\,x^{-1/2}-2\\,x^{-3}=\\frac{1}{2\\sqrt x}-\\frac{2}{x^3}")}<p>Erst umschreiben, dann die Potenzregel anwenden, am Ende wieder zurückschreiben.</p>`],
    ['Sonderfälle', `<ul><li><b>Zahl mal Funktion:</b> ${t('5\\cdot e^x')} braucht keine Produktregel – der Faktor bleibt einfach stehen.</li><li><b>${t('x')} im Exponenten:</b> ${t("(2^x)'=\\ln 2\\cdot 2^x")}. Die Potenzregel gilt nur, wenn ${t('x')} in der Basis steht.</li><li><b>Logarithmus:</b> ${t("(\\ln x)'=\\tfrac 1x")}.</li><li><b>Bruch:</b> Entweder mit der Quotientenregel oder als Produkt mit einer Potenz hoch ${t('-1')} schreiben.</li><li><b>Mehrfach verkettet:</b> von außen nach innen arbeiten und jede innere Ableitung als Faktor anhängen.</li></ul>`],
  ],
  extrema: [
    ['Genauer hingeschaut: Warum der Vorzeichenwechsel entscheidet', `<p>Ist ${t("f'")} erst positiv und dann negativ, steigt der Graph erst und fällt danach – dazwischen muss ein Gipfel liegen. Das ist die eigentliche Begründung. Das Kriterium mit ${t("f''")} ist nur eine bequeme Abkürzung: Ein negatives ${t("f''")} bedeutet, dass ${t("f'")} dort fällt, also von Plus nach Minus wechselt.</p><p>Die Abkürzung versagt, wenn ${t("f''(x_0)=0")} ist. Dann muss man den Vorzeichenwechsel direkt prüfen.</p>`],
    ['Beispiel 2: Wenn die zweite Ableitung null ist', `${D("f(x)=x^4\\qquad f'(x)=4x^3\\qquad f''(x)=12x^2")}<p>${t("f'(x)=0")} bei ${t('x=0')}, aber ${t("f''(0)=0")} – keine Aussage. Vorzeichen von ${t("f'")}: für negative ${t('x')} negativ, für positive positiv. Wechsel von Minus nach Plus: Tiefpunkt ${t('T(0\\mid 0)')}.</p>`],
    ['Beispiel 3: Sattelpunkt', `${D("f(x)=x^3\\qquad f'(x)=3x^2")}<p>Wieder ist ${t("f'(0)=0")}. Aber ${t('3x^2')} ist links und rechts von null positiv – kein Vorzeichenwechsel. Der Graph steigt, wird kurz waagerecht und steigt weiter: ein Sattelpunkt, kein Extrempunkt.</p>`],
    ['Beispiel 4: Größter Wert auf einem Intervall', `<p>${t('f(x)=x^3-3x')} auf dem Intervall ${t('[-3;\\,3]')}. Aus ${t("f'(x)=3x^2-3=0")} folgt ${t('x=\\pm 1')}: Hochpunkt ${t('H(-1\\mid 2)')}, Tiefpunkt ${t('T(1\\mid -2)')}.</p><p>Jetzt die Ränder: ${t('f(-3)=-18')} und ${t('f(3)=18')}. Der größte Wert im Intervall ist also 18 am rechten Rand, der kleinste ${t('-18')} am linken – nicht die Werte an Hoch- und Tiefpunkt.</p>`],
    ['Sonderfälle', `<ul><li><b>Lokal und global:</b> Ein Hochpunkt ist nur in seiner Umgebung der höchste Punkt. Der insgesamt größte Wert kann woanders liegen.</li><li><b>Keine Extrempunkte:</b> Bei ${t('f(x)=x^3+x')} ist ${t("f'(x)=3x^2+1")} nie null – der Graph steigt überall.</li><li><b>Rand:</b> Am Rand eines Intervalls kann der größte Wert liegen, obwohl dort ${t("f'\\ne 0")} ist.</li><li><b>Mehrfache Nullstelle von ${t("f'")}:</b> Bei gerader Vielfachheit gibt es keinen Vorzeichenwechsel.</li></ul>`],
  ],
  integral: [
    ['Genauer hingeschaut: Warum Ableiten und Integrieren zusammengehören', `<p>Sei ${t('A(x)')} die Fläche unter dem Graphen von einer festen Stelle bis ${t('x')}. Geht man ein kleines Stück ${t('h')} weiter, kommt ein schmaler Streifen dazu, der ungefähr ${t('f(x)\\cdot h')} groß ist.</p>${D("\\frac{A(x+h)-A(x)}{h}\\approx f(x)\\quad\\Rightarrow\\quad A'(x)=f(x)")}<p>Die Fläche wächst also genau so schnell, wie der Graph gerade hoch ist. Deshalb findet man Flächen über Stammfunktionen.</p>`],
    ['Beispiel 2: Fläche mit Vorzeichenwechsel', `<p>${t('f(x)=x^2-4')} über ${t('[0;\\,3]')}. Die Nullstelle ${t('x=2')} teilt das Intervall. Stammfunktion: ${t('F(x)=\\tfrac13x^3-4x')}.</p>${D('\\int_0^2 f(x)\\,dx=-\\tfrac{16}{3}\\qquad\\int_2^3 f(x)\\,dx=\\tfrac73')}<p>Fläche: ${t('\\tfrac{16}{3}+\\tfrac73=\\tfrac{23}{3}\\approx 7{,}67')}. Das Integral über das ganze Intervall wäre dagegen nur ${t('-3')} – die Teile heben sich teilweise auf.</p>`],
    ['Beispiel 3: Fläche zwischen zwei Graphen', `<p>${t('f(x)=x')} und ${t('g(x)=x^2')} schneiden sich bei ${t('x=0')} und ${t('x=1')}. Dazwischen liegt die Gerade oben.</p>${D('A=\\int_0^1(x-x^2)\\,dx=\\Bigl[\\tfrac12x^2-\\tfrac13x^3\\Bigr]_0^1=\\tfrac16')}`],
    ['Beispiel 4: Vom Zufluss zur Menge', `<p>In ein Becken fließt Wasser mit der Rate ${t('r(t)=6-2t')} (Liter pro Minute). Wie viel kommt in den ersten 3 Minuten dazu?</p>${D('\\int_0^3(6-2t)\\,dt=\\bigl[6t-t^2\\bigr]_0^3=9')}<p>Es sind 9 Liter. Ab ${t('t=3')} wird die Rate negativ: Dann fließt Wasser ab, und das Integral zählt das von selbst als Abnahme.</p>`],
    ['Sonderfälle', `<ul><li><b>Gleiche Grenzen:</b> ${t('\\int_a^a f(x)\\,dx=0')}.</li><li><b>Grenzen vertauscht:</b> Das Vorzeichen dreht sich um.</li><li><b>Punktsymmetrischer Graph:</b> Über ${t('[-a;\\,a]')} heben sich die Teile genau auf, das Integral ist null.</li><li><b>${t('\\tfrac 1x')}:</b> Die Potenzregel versagt (man müsste durch null teilen). Stammfunktion ist ${t('\\ln|x|')}.</li><li><b>Die Konstante ${t('C')}:</b> Es gibt unendlich viele Stammfunktionen; beim bestimmten Integral fällt ${t('C')} weg.</li></ul>`],
  ],
  kurve: [
    ['Genauer hingeschaut: Drei Funktionen, ein Bild', `<p>${t('f')} gibt die <b>Höhe</b> an, ${t("f'")} die <b>Steigung</b>, ${t("f''")} die <b>Krümmung</b>. Jede Besonderheit des Graphen zeigt sich in einer der drei: Nullstellen in ${t('f')}, Extrempunkte in ${t("f'")}, Wendepunkte in ${t("f''")}. Wer diese Zuordnung im Kopf hat, braucht keine Liste auswendig zu lernen.</p>`],
    ['Beispiel: Vollständige Untersuchung', `${D('f(x)=x^3-3x^2')}<p><b>Nullstellen:</b> ${t('x^2(x-3)=0')}, also ${t('x=0')} (doppelt – der Graph berührt die Achse) und ${t('x=3')}.</p><p><b>Extrempunkte:</b> ${t("f'(x)=3x^2-6x=3x(x-2)")}, also ${t('x=0')} und ${t('x=2')}. Mit ${t("f''(x)=6x-6")}: ${t("f''(0)=-6")}, Hochpunkt ${t('H(0\\mid 0)')}; ${t("f''(2)=6")}, Tiefpunkt ${t('T(2\\mid -4)')}.</p><p><b>Wendepunkt:</b> ${t("f''(x)=0")} bei ${t('x=1')}, und ${t("f'''(x)=6\\ne 0")}: ${t('W(1\\mid -2)')}.</p><p><b>Verhalten:</b> Für große ${t('x')} geht ${t('f')} gegen ${t('+\\infty')}, für sehr kleine gegen ${t('-\\infty')}. Symmetrie liegt keine vor (gerade und ungerade Exponenten gemischt).</p>`],
    ['Beispiel 2: Wendetangente', `<p>Die Tangente im Wendepunkt ${t('W(1\\mid -2)')} hat die Steigung ${t("f'(1)=3-6=-3")}.</p>${D('t(x)=-3\\,(x-1)-2=-3x+1')}<p>Am Wendepunkt fällt dieser Graph am steilsten – steiler als ${t('-3')} wird es nirgends zwischen Hoch- und Tiefpunkt.</p>`],
    ['Sonderfälle', `<ul><li><b>Doppelte Nullstelle:</b> Der Graph berührt die x-Achse und kehrt um. <b>Dreifache:</b> Er geht mit einem Sattel hindurch.</li><li><b>Sattelpunkt:</b> ein Wendepunkt mit waagerechter Tangente.</li><li><b>Gerader Grad:</b> Beide Enden zeigen in dieselbe Richtung. <b>Ungerader Grad:</b> in entgegengesetzte – es gibt mindestens eine Nullstelle.</li><li><b>Mit e-Funktion:</b> Für große ${t('x')} setzt sich ${t('e^x')} gegen jede Potenz durch; ${t('x^2e^{-x}')} geht gegen null.</li></ul>`],
  ],
  extremwert: [
    ['Genauer hingeschaut: Warum die Nebenbedingung nötig ist', `<p>Mit zwei freien Variablen gäbe es kein Maximum: Eine Fläche ${t('x\\cdot y')} lässt sich beliebig groß machen. Erst die Nebenbedingung koppelt die beiden – wird die eine Seite länger, muss die andere kürzer werden. Dieser Gegensatz erzeugt das Optimum, und durch das Einsetzen wird er in einer einzigen Funktion sichtbar.</p>`],
    ['Beispiel 2: Die Schachtel', `<p>Aus einem quadratischen Blech (12 cm Seitenlänge) werden an den Ecken Quadrate der Länge ${t('x')} ausgeschnitten, die Ränder werden hochgebogen.</p>${D('V(x)=x\\,(12-2x)^2\\qquad 0<x<6')}<p>Ausmultipliziert: ${t('V(x)=4x^3-48x^2+144x')}. Ableitung:</p>${D("V'(x)=12x^2-96x+144\\qquad V'(x)=12\\,(x-2)(x-6)")}<p>Im erlaubten Bereich liegt nur ${t('x=2')}. Mit ${t("V''(2)=-48<0")} ist es ein Maximum: ${t('V(2)=2\\cdot 8^2=128')} cm³.</p>`],
    ['Beispiel 3: Die sparsamste Dose', `<p>Eine zylindrische Dose soll 1 Liter (1000 cm³) fassen und möglichst wenig Blech brauchen.</p>${D('O=2\\pi r^2+2\\pi r\\,h\\qquad\\pi r^2h=1000')}<p>Aus der Nebenbedingung: ${t('h=\\tfrac{1000}{\\pi r^2}')}. Eingesetzt:</p>${D("O(r)=2\\pi r^2+\\frac{2000}{r}\\qquad O'(r)=4\\pi r-\\frac{2000}{r^2}")}<p>${t("O'(r)=0")} führt auf ${t('r^3=\\tfrac{500}{\\pi}')}, also ${t('r\\approx 5{,}42')} cm und ${t('h\\approx 10{,}84')} cm. Bemerkenswert: Die Höhe ist genau der Durchmesser.</p>`],
    ['Beispiel 4: Rechteck unter der Parabel', `<p>Unter ${t('f(x)=4-x^2')} soll ein Rechteck mit größter Fläche liegen, das auf der x-Achse steht. Seine Ecken sind ${t('(\\pm x\\mid 0)')} und ${t('(\\pm x\\mid f(x))')}.</p>${D("A(x)=2x\\,(4-x^2)=8x-2x^3\\qquad A'(x)=8-6x^2")}<p>${t("A'(x)=0")} bei ${t('x=\\sqrt{4/3}\\approx 1{,}15')}. Die größte Fläche ist ${t('A\\approx 6{,}16')}.</p>`],
    ['Sonderfälle', `<ul><li><b>Maximum am Rand:</b> Darf beim Gehege aus dem ersten Beispiel ${t('x')} höchstens 8 m sein, ist ${t('x=10')} nicht erlaubt. Die Fläche wächst bis zum Rand: beste Lösung ${t('x=8')} mit ${t('A=8\\cdot 24=192')} m².</li><li><b>Nur ganze Zahlen möglich:</b> Dann die beiden Nachbarn des berechneten Werts vergleichen.</li><li><b>Minimum statt Maximum:</b> gleiche Rechnung, aber ${t("f''>0")} prüfen.</li><li><b>Mehrere Kandidaten:</b> alle Funktionswerte vergleichen, auch die an den Rändern.</li></ul>`],
  ],
  anwenden: [
    ['Genauer hingeschaut: Symmetrie spart Arbeit', `<p>Ist der gesuchte Graph <b>achsensymmetrisch</b> zur y-Achse, kommen nur gerade Exponenten vor: ${t('f(x)=ax^4+bx^2+c')}. Ist er <b>punktsymmetrisch</b> zum Ursprung, nur ungerade: ${t('f(x)=ax^3+bx')}. Damit halbiert sich die Zahl der Unbekannten – und der Bedingungen, die man braucht.</p>`],
    ['Beispiel 2: Tangente mit vorgegebener Steigung', `<p>An welcher Stelle ist die Tangente an ${t('f(x)=x^2-2x')} parallel zur Geraden ${t('y=4x')}? Parallel heißt gleiche Steigung:</p>${D("f'(x)=2x-2=4\\quad\\Rightarrow\\quad x=3")}<p>Berührpunkt: ${t('f(3)=3')}. Tangente: ${t('t(x)=4\\,(x-3)+3=4x-9')}.</p>`],
    ['Beispiel 3: Steckbrief mit Symmetrie', `<p>Gesucht ist eine punktsymmetrische Funktion dritten Grades mit Hochpunkt ${t('H(1\\mid 2)')}. Ansatz: ${t('f(x)=ax^3+bx')}, also ${t("f'(x)=3ax^2+b")}.</p>${D("f(1)=a+b=2\\qquad f'(1)=3a+b=0")}<p>Abziehen: ${t('2a=-2')}, also ${t('a=-1')} und ${t('b=3')}.</p>${D('f(x)=-x^3+3x')}<p>Kontrolle, ob es wirklich ein Hochpunkt ist: ${t("f''(x)=-6x")}, ${t("f''(1)=-6<0")}. Passt.</p>`],
    ['Beispiel 4: Ortskurve einer Schar', `${D("f_k(x)=x^3-3kx\\qquad k>0")}<p>${t("f_k'(x)=3x^2-3k=0")} bei ${t('x=\\pm\\sqrt k')}. Der Tiefpunkt liegt bei ${t('x=\\sqrt k')} mit ${t('y=k\\sqrt k-3k\\sqrt k=-2k\\sqrt k')}.</p><p>Ortskurve: Aus ${t('x=\\sqrt k')} folgt ${t('k=x^2')}. Einsetzen: ${t('y=-2x^2\\cdot x=-2x^3')} (für ${t('x>0')}). Auf dieser Kurve liegen die Tiefpunkte aller Scharfunktionen.</p>`],
    ['Sonderfälle', `<ul><li><b>Bedingung erfüllt, Eigenschaft nicht:</b> ${t("f'(x_0)=0")} macht noch keinen Extrempunkt. Am Ende eines Steckbriefs immer prüfen.</li><li><b>Fallunterscheidung bei Scharen:</b> Für ${t('k>0')}, ${t('k=0')} und ${t('k<0')} kann der Graph ganz verschieden aussehen – bei ${t('f_k')} oben gibt es für ${t('k\\le 0')} gar keine Extrempunkte.</li><li><b>Gemeinsame Punkte einer Schar:</b> Punkte, deren Koordinaten nicht von ${t('k')} abhängen (hier der Ursprung).</li><li><b>Senkrechte Tangente:</b> Sie lässt sich nicht in der Form ${t('y=mx+b')} schreiben.</li></ul>`],
  ],
  expln: [
    ['Genauer hingeschaut: Was an der Zahl e besonders ist', `<p>Jede Exponentialfunktion ${t('a^x')} ist proportional zu ihrer eigenen Ableitung – die Steigung ist überall ein festes Vielfaches der Höhe. Bei genau einer Basis ist dieses Vielfache 1: bei ${t('e\\approx 2{,}718')}. Deshalb ist ${t('e^x')} seine eigene Ableitung.</p>${D("a^x=e^{x\\cdot\\ln a}\\qquad (a^x)'=\\ln a\\cdot a^x")}<p>Jede andere Basis lässt sich so auf ${t('e')} zurückführen.</p>`],
    ['Beispiel 2: Gleichung mit Substitution', `${D('e^{2x}-5\\,e^{x}+6=0')}<p>Weil ${t('e^{2x}=(e^x)^2')} ist, hilft die Ersetzung ${t('z=e^x')}: ${t('z^2-5z+6=0')} mit den Lösungen ${t('z=2')} und ${t('z=3')}. Zurück: ${t('x=\\ln 2\\approx 0{,}69')} und ${t('x=\\ln 3\\approx 1{,}10')}.</p>`],
    ['Beispiel 3: Halbwertszeit', `<p>Ein Stoff zerfällt nach ${t('N(t)=N_0\\cdot e^{-0{,}2t}')} (${t('t')} in Tagen). Nach welcher Zeit ist die Hälfte übrig?</p>${D('e^{-0{,}2t}=\\tfrac12\\quad\\Rightarrow\\quad t=\\frac{\\ln 2}{0{,}2}\\approx 3{,}47')}<p>Nach weiteren 3,47 Tagen ist wieder die Hälfte weg – also ein Viertel übrig. Die Halbwertszeit hängt nicht von der Startmenge ab.</p>`],
    ['Beispiel 4: Mit dem Logarithmus ableiten', `${D("f(x)=x\\cdot\\ln x\\qquad f'(x)=\\ln x+1")}<p>(Produktregel: ${t('1\\cdot\\ln x+x\\cdot\\tfrac 1x')}.) ${t("f'(x)=0")} bei ${t('\\ln x=-1')}, also ${t('x=\\tfrac 1e\\approx 0{,}37')}. Dort liegt der Tiefpunkt ${t('T\\bigl(\\tfrac1e\\mid -\\tfrac1e\\bigr)')}.</p>`],
    ['Sonderfälle', `<ul><li><b>${t('e^x')} wird nie null:</b> Ein Produkt wie ${t('(x-2)\\,e^x=0')} ist nur null, wenn die Klammer null ist.</li><li><b>${t('\\ln x')} gibt es nur für ${t('x>0')}.</b> Eine berechnete Lösung, die das verletzt, fällt weg.</li><li><b>Feste Werte:</b> ${t('\\ln 1=0')}, ${t('\\ln e=1')}, ${t('e^0=1')}.</li><li><b>Negativer Exponent:</b> ${t('e^{-x}')} fällt und nähert sich der x-Achse, erreicht sie aber nie.</li><li><b>Keine Lösung:</b> ${t('e^x=-3')} ist unlösbar.</li></ul>`],
  ],
  'a-gebrochen': [
    ['Genauer hingeschaut: Polstellen mit und ohne Vorzeichenwechsel', `<p>Wird der Nenner an einer Stelle <b>einfach</b> null, wechselt er dort das Vorzeichen – der Graph springt von ${t('-\\infty')} nach ${t('+\\infty')} (oder umgekehrt). Bei einer <b>doppelten</b> Nullstelle des Nenners, wie bei ${t('\\tfrac{1}{x^2}')}, bleibt das Vorzeichen gleich: Beide Äste laufen in dieselbe Richtung.</p>`],
    ['Beispiel 2: Ein Loch statt einer Polstelle', `${D('f(x)=\\frac{x^2-4}{x-2}=\\frac{(x-2)(x+2)}{x-2}=x+2')}<p>Bei ${t('x=2')} ist der Nenner null, die Funktion also nicht definiert. Weil sich der Faktor kürzen lässt, schießt der Graph dort aber nicht ins Unendliche: Er ist die Gerade ${t('y=x+2')} mit einem Loch im Punkt ${t('(2\\mid 4)')}.</p>`],
    ['Beispiel 3: Schräge Asymptote', `${D('f(x)=\\frac{x^2+1}{x}=x+\\frac 1x')}<p>Für große ${t('x')} wird ${t('\\tfrac 1x')} winzig – der Graph schmiegt sich an die Gerade ${t('y=x')}. Bei ${t('x=0')} liegt eine Polstelle.</p>${D("f'(x)=1-\\frac{1}{x^2}=0\\quad\\Rightarrow\\quad x=\\pm 1")}<p>Tiefpunkt ${t('T(1\\mid 2)')} und Hochpunkt ${t('H(-1\\mid -2)')}. Kurios: Der Hochpunkt liegt tiefer als der Tiefpunkt – die Polstelle trennt die beiden Äste.</p>`],
    ['Sonderfälle', `<ul><li><b>Nenner wird nie null:</b> ${t('\\tfrac{1}{x^2+1}')} hat keine Lücke und keine Polstelle.</li><li><b>Zähler ist eine Zahl:</b> Dann gibt es keine Nullstellen.</li><li><b>Erst vereinfachen, dann ableiten:</b> Wer ${t('\\tfrac{x^2+1}{x}')} als ${t('x+x^{-1}')} schreibt, spart sich die Quotientenregel.</li><li><b>Zählergrad viel größer:</b> Der Graph verhält sich im Unendlichen wie eine Parabel oder höher – eine Gerade als Asymptote gibt es dann nicht.</li></ul>`],
  ],
  'a-trig': [
    ['Genauer hingeschaut: Sinus und Kosinus am Einheitskreis', `<p>Läuft ein Punkt auf einem Kreis mit Radius 1, ist seine Höhe der Sinus des Winkels und sein waagerechter Abstand von der Mitte der Kosinus. Daraus folgt für jeden Winkel:</p>${D('\\sin^2 x+\\cos^2 x=1')}<p>Auch die Ableitung sieht man hier: Bei ${t('x=0')} bewegt sich der Punkt senkrecht nach oben – die Höhe wächst am schnellsten, mit der Rate 1, und ${t('\\cos 0=1')}. Ganz oben steht die Höhe kurz still, und ${t('\\cos\\tfrac{\\pi}{2}=0')}.</p>`],
    ['Beispiel 2: Wasserstand im Hafen', `<p>${t('h(t)=2\\sin\\bigl(\\tfrac{\\pi}{6}\\,t\\bigr)+5')} beschreibt den Wasserstand in Metern, ${t('t')} in Stunden.</p><p>Periode: ${t('2\\pi:\\tfrac{\\pi}{6}=12')} Stunden. Höchststand 7 m (zum ersten Mal bei ${t('t=3')}), Tiefststand 3 m.</p>${D("h'(t)=\\frac{\\pi}{3}\\cos\\Bigl(\\frac{\\pi}{6}\\,t\\Bigr)")}<p>Bei ${t('t=0')} steigt das Wasser am schnellsten: ${t("h'(0)=\\tfrac{\\pi}{3}\\approx 1{,}05")} Meter pro Stunde.</p>`],
    ['Beispiel 3: Eine Sinus-Gleichung lösen', `<p>Gesucht sind alle Lösungen von ${t('\\sin x=0{,}5')} im Bereich ${t('[0;\\,2\\pi]')}. Der Taschenrechner liefert ${t('x_1=\\tfrac{\\pi}{6}')}. Wegen der Symmetrie des Sinusbogens gibt es eine zweite Lösung:</p>${D('x_2=\\pi-\\frac{\\pi}{6}=\\frac{5\\pi}{6}')}`],
    ['Sonderfälle', `<ul><li><b>Unendlich viele Lösungen:</b> Ohne eingeschränkten Bereich wiederholt sich jede Lösung nach jeder Periode.</li><li><b>Volle Periode:</b> Das Integral von Sinus oder Kosinus über eine ganze Periode ist null – Berg und Tal heben sich auf.</li><li><b>Tangens:</b> Er ist bei ${t('\\tfrac{\\pi}{2}')} nicht definiert, weil dort der Kosinus null ist.</li><li><b>Keine Lösung:</b> ${t('\\sin x=2')} ist unlösbar – Sinus und Kosinus liegen immer zwischen ${t('-1')} und ${t('1')}.</li></ul>`],
  ],
  'a-rotation': [
    ['Genauer hingeschaut: Probe an der Kugel', `<p>Der Halbkreis ${t('f(x)=\\sqrt{r^2-x^2}')} über ${t('[-r;\\,r]')} erzeugt bei Drehung eine Kugel. Stimmt die Formel, muss das bekannte Kugelvolumen herauskommen:</p>${D('V=\\pi\\int_{-r}^{r}(r^2-x^2)\\,dx=\\pi\\Bigl[r^2x-\\tfrac13x^3\\Bigr]_{-r}^{r}=\\tfrac43\\pi r^3')}<p>Das Quadrat hebt die Wurzel auf – deshalb sind Rotationsaufgaben mit Wurzelfunktionen oft besonders angenehm.</p>`],
    ['Beispiel 2: Ein Hohlkörper', `<p>Dreht sich die Fläche <b>zwischen</b> zwei Graphen um die x-Achse, zieht man das innere Volumen vom äußeren ab:</p>${D('V=\\pi\\int_a^b\\bigl(f(x)^2-g(x)^2\\bigr)\\,dx')}<p>Für ${t('f(x)=\\sqrt x')} und ${t('g(x)=x')} über ${t('[0;\\,1]')}:</p>${D('V=\\pi\\int_0^1(x-x^2)\\,dx=\\tfrac{\\pi}{6}\\approx 0{,}52')}`],
    ['Beispiel 3: Fläche unter einer fallenden e-Funktion', `${D('\\int_0^{b}e^{-x}\\,dx=\\bigl[-e^{-x}\\bigr]_0^{b}=1-e^{-b}')}<p>Für ${t('b\\to\\infty')} geht ${t('e^{-b}')} gegen null. Die Fläche, die sich unendlich weit nach rechts zieht, ist genau 1.</p>`],
    ['Sonderfälle', `<ul><li><b>Unendliche Fläche, endliches Volumen:</b> Unter ${t('\\tfrac 1x')} ab ${t('x=1')} liegt eine unendlich große Fläche. Der zugehörige Rotationskörper hat trotzdem nur das Volumen ${t('\\pi\\int_1^\\infty\\tfrac{1}{x^2}\\,dx=\\pi')}.</li><li><b>Lücke am Rand:</b> ${t('\\tfrac{1}{\\sqrt x}')} wird bei null unendlich groß; die Fläche über ${t('(0;\\,1]')} ist dennoch endlich, nämlich 2.</li><li><b>Hohlkörper:</b> ${t('f^2-g^2')} ist etwas anderes als ${t('(f-g)^2')}.</li><li><b>Drehung um die y-Achse:</b> Man braucht die Umkehrfunktion und integriert über ${t('y')}.</li></ul>`],
  ],
  'a-wachstum': [
    ['Genauer hingeschaut: Drei Modelle, drei Änderungsregeln', `<p>Jedes Wachstumsmodell beantwortet die Frage „Wovon hängt die Änderung ab?“ anders:</p><ul><li><b>Exponentiell:</b> vom Bestand. ${t("f'=k\\cdot f")}</li><li><b>Begrenzt:</b> von dem, was noch fehlt. ${t("f'=k\\cdot(S-f)")}</li><li><b>Logistisch:</b> von beidem. ${t("f'=\\tfrac kS\\cdot f\\cdot(S-f)")}</li></ul><p>Beim logistischen Wachstum ist das Produkt ${t('f\\cdot(S-f)')} am größten, wenn beide Faktoren gleich sind – also bei ${t('f=\\tfrac S2')}. Deshalb liegt dort das stärkste Wachstum.</p>`],
    ['Beispiel 2: Parameter aus Messwerten', `<p>Ein Bestand wächst begrenzt gegen ${t('S=100')}, startet bei 20 und ist nach 5 Tagen bei 60.</p><p>Aus ${t('f(0)=100-a=20')} folgt ${t('a=80')}. Dann: ${t('100-80\\,e^{-5k}=60')}, also ${t('e^{-5k}=0{,}5')}.</p>${D('k=\\frac{\\ln 2}{5}\\approx 0{,}139\\qquad f(t)=100-80\\,e^{-0{,}139\\,t}')}`],
    ['Beispiel 3: Wann sind 90 % erreicht?', `<p>Logistisch mit ${t('S=1000')}, ${t('a=9')}, ${t('k=0{,}5')}. Gesucht ist ${t('t')} mit ${t('f(t)=900')}.</p>${D('\\frac{1000}{1+9\\,e^{-0{,}5t}}=900\\quad\\Rightarrow\\quad 9\\,e^{-0{,}5t}=\\tfrac19')}<p>Also ${t('e^{-0{,}5t}=\\tfrac{1}{81}')} und ${t('t=\\tfrac{\\ln 81}{0{,}5}\\approx 8{,}8')}. Zum Vergleich: Die Hälfte war schon bei ${t('t\\approx 4{,}4')} erreicht – für die zweite Hälfte bis 90 % braucht es noch einmal genauso lange.</p>`],
    ['Sonderfälle', `<ul><li><b>Start über der Grenze:</b> Dann ist ${t('a')} negativ und der Bestand <b>sinkt</b> auf ${t('S')} – wie beim abkühlenden Tee.</li><li><b>Logistisch mit ${t('a=1')}:</b> Der Bestand startet genau bei der halben Grenze; das stärkste Wachstum liegt bei ${t('t=0')}.</li><li><b>Die Grenze wird nie erreicht:</b> Der Abstand wird nur immer kleiner. Gefragt wird deshalb nach „99 %“ oder „bis auf 1 Einheit“.</li><li><b>Lineares Wachstum zum Vergleich:</b> Die Änderung ist konstant – der Bestand hat weder Grenze noch Beschleunigung.</li></ul>`],
  ],
  's-grund': [
    ['Genauer hingeschaut: Wann die Laplace-Formel nicht gilt', `<p>„Günstige durch mögliche“ setzt voraus, dass alle Ergebnisse gleich wahrscheinlich sind. Bei der Augensumme zweier Würfel ist das nicht so: Die Summe 2 entsteht nur durch (1;1), die Summe 7 auf sechs Arten. Gleich wahrscheinlich sind hier die 36 <b>Paare</b>, nicht die 11 Summen.</p>${D('P(\\text{Summe }7)=\\tfrac{6}{36}=\\tfrac16\\qquad P(\\text{Summe }2)=\\tfrac{1}{36}')}`],
    ['Beispiel 2: Vierfeldertafel ausfüllen', `<p>An einer Schule sind 200 Jugendliche, davon 120 Mädchen. 90 sind im Sportverein, darunter 50 Mädchen.</p><p>Daraus folgt Schritt für Schritt: 80 Jungen; 40 Jungen im Verein (${t('90-50')}); 70 Mädchen und 40 Jungen ohne Verein. Kontrolle: ${t('50+40+70+40=200')}.</p><p>Wahrscheinlichkeit, zufällig einen Jungen aus dem Verein zu treffen: ${t('\\tfrac{40}{200}=0{,}2')}.</p>`],
    ['Beispiel 3: Prozent rückwärts', `<p>Nach 20 % Rabatt kostet eine Jacke 60 €. Der alte Preis ist <b>nicht</b> ${t('60+20\\,\\%')}. Die 60 € sind 80 % des alten Preises:</p>${D('G=\\frac{60}{0{,}8}=75')}`],
    ['Beispiel 4: Prozent und Prozentpunkte', `<p>Steigt ein Anteil von 20 % auf 25 %, sind das 5 <b>Prozentpunkte</b> – aber ein Anstieg um 25 <b>Prozent</b>, denn ${t('\\tfrac{5}{20}=0{,}25')}. In Zeitungsmeldungen wird das oft verwechselt.</p>`],
    ['Beispiel 5: Mehrmals hintereinander Prozente', `<p>1000 € werden drei Jahre lang mit 2 % verzinst. Jedes Jahr wird mit ${t('1{,}02')} malgenommen – auch die Zinsen des Vorjahres wachsen mit:</p>${D('1000\\cdot 1{,}02^3\\approx 1061{,}21')}<p>Das sind 1,21 € mehr als dreimal 20 €. Über lange Zeiträume wird aus diesem kleinen Unterschied ein großer – das ist exponentielles Wachstum.</p>`],
    ['Sonderfälle', `<ul><li><b>Sicher und unmöglich:</b> Wahrscheinlichkeit 1 bzw. 0. Alle Wahrscheinlichkeiten eines Versuchs ergeben zusammen 1.</li><li><b>„Oder“ mit Überschneidung:</b> ${t('P(A\\cup B)=P(A)+P(B)-P(A\\cap B)')} – sonst wird das Gemeinsame doppelt gezählt.</li><li><b>Wenige Versuche:</b> Nach 10 Würfen kann die relative Häufigkeit weit von der Wahrscheinlichkeit entfernt liegen.</li></ul>`],
  ],
  's-labor': [
    ['Genauer hingeschaut: Warum der Binomialkoeffizient dazugehört', `<p>Bei drei Versuchen gibt es für „genau zwei Treffer“ drei Pfade: TTN, TNT und NTT. Jeder hat dieselbe Wahrscheinlichkeit ${t('p^2\\,(1-p)')}, weil es beim Malnehmen nicht auf die Reihenfolge ankommt. Also: ein Pfad mal Anzahl der Pfade – und die Anzahl ist ${t('\\binom32=3')}.</p>`],
    ['Beispiel 2: Ein Bereich', `<p>${t('n=20')}, ${t('p=0{,}3')}. Wie wahrscheinlich sind 4 bis 8 Treffer?</p>${D('P(4\\le X\\le 8)=P(X\\le 8)-P(X\\le 3)')}<p>Aus der Tabelle: ${t('0{,}8867-0{,}1071=0{,}7796')}. Wichtig ist die 3: Die 4 soll ja noch dazugehören.</p>`],
    ['Beispiel 3: Wie oft muss man es versuchen?', `<p>Ein Los gewinnt mit ${t('p=0{,}1')}. Wie viele Lose braucht man, um mit mindestens 95 % Wahrscheinlichkeit wenigstens einmal zu gewinnen?</p>${D('1-0{,}9^n\\ge 0{,}95\\quad\\Rightarrow\\quad 0{,}9^n\\le 0{,}05')}<p>Logarithmieren: ${t('n\\ge\\tfrac{\\ln 0{,}05}{\\ln 0{,}9}\\approx 28{,}4')}. Man braucht also 29 Lose. (Beim Teilen durch ${t('\\ln 0{,}9')} dreht sich das Zeichen um, weil diese Zahl negativ ist.)</p>`],
    ['Beispiel 4: Typische Trefferzahlen', `<p>${t('n=100')}, ${t('p=0{,}2')}: ${t('\\mu=20')} und ${t('\\sigma=\\sqrt{100\\cdot 0{,}2\\cdot 0{,}8}=4')}. In etwa zwei von drei Fällen liegt die Trefferzahl zwischen 16 und 24. 35 Treffer wären fast vier ${t('\\sigma')} entfernt – das wäre ein starker Hinweis, dass ${t('p')} in Wahrheit größer ist.</p>`],
    ['Sonderfälle', `<ul><li><b>Kein Treffer:</b> ${t('P(X=0)=(1-p)^n')} – der Binomialkoeffizient ist 1.</li><li><b>${t('p=0{,}5')}:</b> Die Verteilung ist symmetrisch um ${t('\\tfrac n2')}.</li><li><b>${t('n=1')}:</b> ein einzelner Bernoulli-Versuch.</li><li><b>Erwartungswert keine ganze Zahl:</b> ${t('\\mu=2{,}5')} ist kein mögliches Ergebnis, sondern ein Durchschnitt.</li><li><b>Treffer und Niete vertauschen:</b> „Höchstens 2 Nieten“ ist dasselbe wie „mindestens ${t('n-2')} Treffer“.</li></ul>`],
  ],
  's-baum': [
    ['Genauer hingeschaut: Warum entlang eines Pfades multipliziert wird', `<p>„Die Hälfte kommt durch die erste Runde, davon ein Drittel durch die zweite“: Ein Drittel <b>von</b> der Hälfte ist ein Sechstel. Jede Stufe nimmt einen Anteil von dem, was die vorige übrig gelassen hat – und „Anteil von“ heißt malnehmen. Verschiedene Pfade schließen sich dagegen aus, deshalb werden sie addiert.</p>`],
    ['Beispiel 2: Verschiedene Farben', `<p>In einer Urne sind 5 rote und 3 blaue Kugeln. Zwei werden ohne Zurücklegen gezogen. Wie wahrscheinlich sind zwei verschiedene Farben?</p>${D('\\tfrac58\\cdot\\tfrac37+\\tfrac38\\cdot\\tfrac57=\\tfrac{30}{56}=\\tfrac{15}{28}\\approx 0{,}54')}<p>Es gibt zwei passende Pfade (rot–blau und blau–rot). Sie sind hier gleich wahrscheinlich – das ist bei „ohne Zurücklegen“ kein Zufall, aber nachrechnen muss man es trotzdem.</p>`],
    ['Beispiel 3: Warten auf den ersten Erfolg', `<p>Es wird gewürfelt, bis eine Sechs fällt – höchstens dreimal. Wahrscheinlichkeit für einen Erfolg:</p>${D('\\tfrac16+\\tfrac56\\cdot\\tfrac16+\\tfrac56\\cdot\\tfrac56\\cdot\\tfrac16=\\tfrac{91}{216}\\approx 0{,}42')}<p>Schneller über das Gegenteil: ${t('1-\\bigl(\\tfrac56\\bigr)^3=1-\\tfrac{125}{216}')}. Beide Wege liefern dasselbe.</p>`],
    ['Sonderfälle', `<ul><li><b>Kontrolle:</b> An jeder Verzweigung ergeben die Wahrscheinlichkeiten zusammen 1, ebenso alle Pfade am Ende.</li><li><b>Baum abkürzen:</b> Interessiert nur „Sechs“ oder „keine Sechs“, genügen zwei Äste statt sechs.</li><li><b>Mit Zurücklegen:</b> Auf jeder Stufe stehen dieselben Zahlen.</li><li><b>Pfad endet früher:</b> Ist das Spiel nach einem Ergebnis vorbei, hört der Ast dort auf.</li></ul>`],
  ],
  's-bedingt': [
    ['Genauer hingeschaut: Die Bedingung verkleinert die Welt', `${D('P_B(A)=\\frac{P(A\\cap B)}{P(B)}')}<p>Weiß man, dass ${t('B')} eingetreten ist, zählen nur noch die Fälle, in denen ${t('B')} gilt. Unter ihnen sucht man den Anteil, in dem auch ${t('A')} gilt. Im Baumdiagramm sind bedingte Wahrscheinlichkeiten genau die Zahlen an den Ästen der zweiten Stufe.</p>`],
    ['Beispiel 2: Der überraschende Test', `<p>1 % einer Bevölkerung hat eine Krankheit. Ein Test erkennt 95 % der Kranken, schlägt aber auch bei 10 % der Gesunden an. Jemand wird positiv getestet – wie wahrscheinlich ist er krank?</p>${D('P(\\text{positiv})=0{,}01\\cdot 0{,}95+0{,}99\\cdot 0{,}10=0{,}1085')}${D('P_{\\text{positiv}}(\\text{krank})=\\frac{0{,}0095}{0{,}1085}\\approx 0{,}088')}<p>Nur knapp 9 %. Der Grund: Es gibt so viele Gesunde, dass ihre falschen Alarme die echten Fälle weit übertreffen.</p>`],
    ['Beispiel 3: Zwei Richtungen in der Vierfeldertafel', `<p>200 Jugendliche, 120 Mädchen, 90 im Sportverein, darunter 50 Mädchen.</p><p>Anteil der Vereinsmitglieder unter den Mädchen: ${t('\\tfrac{50}{120}\\approx 0{,}42')}. Anteil der Mädchen unter den Vereinsmitgliedern: ${t('\\tfrac{50}{90}\\approx 0{,}56')}. Gleicher Zähler, anderer Nenner – je nachdem, welche Gruppe die Bedingung ist.</p>`],
    ['Beispiel 4: Unabhängig oder nicht?', `<p>Mit denselben Zahlen: ${t('P(M)=0{,}6')}, ${t('P(V)=0{,}45')}, ${t('P(M\\cap V)=0{,}25')}. Wären „Mädchen“ und „Verein“ unabhängig, müsste ${t('0{,}6\\cdot 0{,}45=0{,}27')} herauskommen. Tut es nicht – die Merkmale hängen zusammen (Jungen sind hier etwas häufiger im Verein).</p>`],
    ['Sonderfälle', `<ul><li><b>Unabhängig:</b> ${t('P_B(A)=P(A)')} – die Bedingung ändert nichts.</li><li><b>Unvereinbar ist nicht unabhängig:</b> Schließen sich zwei Ereignisse aus, ist ${t('P_B(A)=0')}. Sie beeinflussen sich also maximal.</li><li><b>Bedingung mit Wahrscheinlichkeit 0:</b> Die bedingte Wahrscheinlichkeit ist dann nicht definiert.</li><li><b>Umkehren:</b> ${t('P_B(A)')} und ${t('P_A(B)')} können sehr verschieden sein – siehe Beispiel 2.</li></ul>`],
  ],
  's-verteilung': [
    ['Genauer hingeschaut: Von der Binomial- zur Normalverteilung', `<p>Zeichnet man eine Binomialverteilung für großes ${t('n')} als Säulendiagramm, entsteht eine Glockenform. Die Normalverteilung mit ${t('\\mu=n\\,p')} und ${t('\\sigma=\\sqrt{n\\,p\\,(1-p)}')} legt eine glatte Kurve darüber. Deshalb gelten die Sigma-Regeln für beide – bei der Binomialverteilung allerdings nur als gute Näherung, sobald ${t('\\sigma>3')} ist.</p>`],
    ['Beispiel 2: Zwischen zwei Werten', `<p>Tüten werden mit ${t('\\mu=500')} g und ${t('\\sigma=10')} g befüllt. Wie viele wiegen zwischen 485 g und 510 g?</p>${D('z_1=\\frac{485-500}{10}=-1{,}5\\qquad z_2=\\frac{510-500}{10}=1')}${D('\\Phi(1)-\\Phi(-1{,}5)=0{,}8413-0{,}0668=0{,}7745')}<p>Gut 77 %. Den Wert für ${t('-1{,}5')} bekommt man aus der Tabelle über ${t('\\Phi(-1{,}5)=1-\\Phi(1{,}5)')}.</p>`],
    ['Beispiel 3: Rückwärts – zu einer Wahrscheinlichkeit den Wert finden', `<p>Welches Gewicht wird von 95 % der Tüten unterschritten? Zu ${t('\\Phi(z)=0{,}95')} gehört ${t('z\\approx 1{,}645')}. Zurückrechnen:</p>${D('x=\\mu+z\\cdot\\sigma=500+1{,}645\\cdot 10\\approx 516{,}5')}`],
    ['Beispiel 4: Ist das noch Zufall?', `<p>400 Münzwürfe: ${t('\\mu=200')}, ${t('\\sigma=\\sqrt{400\\cdot 0{,}5\\cdot 0{,}5}=10')}. Mit etwa 95 % Wahrscheinlichkeit liegt die Zahl der „Kopf“-Würfe zwischen 180 und 220. Fällt 230-mal Kopf, sind das drei ${t('\\sigma')} Abstand – bei einer fairen Münze passiert das nur in etwa 3 von 1000 Fällen.</p>`],
    ['Sonderfälle', `<ul><li><b>Genau in der Mitte:</b> ${t('\\Phi(0)=0{,}5')} – die Hälfte liegt unter dem Mittelwert.</li><li><b>Einzelner Wert:</b> Bei der Normalverteilung ist ${t('P(X=x)=0')}; nur Bereiche haben eine Wahrscheinlichkeit.</li><li><b>Kleines ${t('\\sigma')}:</b> schmale, hohe Glocke. <b>Großes ${t('\\sigma')}:</b> breite, flache. Die Fläche darunter ist immer 1.</li><li><b>${t('\\sigma\\le 3')}:</b> Die Sigma-Regeln sind für die Binomialverteilung dann zu ungenau – exakt rechnen.</li></ul>`],
  ],
  's-test': [
    ['Genauer hingeschaut: Die Logik dahinter', `<p>Ein Hypothesentest funktioniert wie ein Gerichtsverfahren. Die Nullhypothese ist der Angeklagte: Sie gilt, bis die Beweise erdrückend sind. „Erdrückend“ heißt: Das beobachtete Ergebnis wäre, wenn ${t('H_0')} stimmt, extrem unwahrscheinlich. Ein Freispruch (keine Ablehnung) beweist die Unschuld nicht – die Beweise haben nur nicht gereicht.</p><p>Deshalb kommt in ${t('H_1')} das, was man <b>zeigen</b> möchte, und in ${t('H_0')} das Gegenteil.</p>`],
    ['Beispiel 2: Linksseitiger Test', `<p>Ein Händler verspricht: mindestens 80 % der Samen keimen. Ein Kunde vermutet weniger und sät 20 Samen, ${t('\\alpha=5\\,\\%')}.</p>${D('H_0:\\ p\\ge 0{,}8\\qquad H_1:\\ p<0{,}8')}<p>Jetzt sprechen <b>kleine</b> Zahlen gegen ${t('H_0')}. Gesucht ist das größte ${t('k')} mit ${t('P(X\\le k)\\le 0{,}05')} für ${t('B(20;\\,0{,}8)')}: ${t('P(X\\le 12)\\approx 0{,}032')} passt, ${t('P(X\\le 13)\\approx 0{,}087')} ist zu groß.</p><p><b>Ablehnungsbereich:</b> 0 bis 12 gekeimte Samen.</p>`],
    ['Beispiel 3: Die Entscheidung', `<p>Keimen 11 Samen, liegt das Ergebnis im Ablehnungsbereich: Die Angabe des Händlers wird verworfen. Keimen 14, liegt es außerhalb: Man kann dem Händler nichts nachweisen – obwohl 14 von 20 nur 70 % sind. Bei so wenigen Samen ist diese Abweichung noch mit Zufall erklärbar.</p>`],
    ['Beispiel 4: Wie oft bleibt ein Schwindel unentdeckt?', `<p>Angenommen, in Wahrheit keimen nur 60 %. Der Test bemerkt das nicht, wenn trotzdem 13 oder mehr Samen keimen:</p>${D('P(X\\ge 13)=1-P(X\\le 12)\\approx 0{,}42\\qquad\\text{mit } B(20;\\,0{,}6)')}<p>In 42 % der Fälle bliebe der Schwindel also unentdeckt (Fehler 2. Art). Mit 100 statt 20 Samen wäre der Test viel schärfer.</p>`],
    ['Sonderfälle', `<ul><li><b>Zweiseitiger Test:</b> Soll nur „anders als behauptet“ gezeigt werden, wird ${t('\\alpha')} auf beide Seiten verteilt – je die Hälfte.</li><li><b>Ergebnis genau auf der Grenze:</b> Es gehört zum Ablehnungsbereich.</li><li><b>Kleineres ${t('\\alpha')}:</b> Man irrt seltener beim Ablehnen, übersieht aber mehr.</li><li><b>Tatsächliches Risiko:</b> Es ist oft kleiner als ${t('\\alpha')} – hier 3,2 % statt 5 %, weil nur ganze Zahlen möglich sind.</li></ul>`],
  ],
  's-kombi': [
    ['Genauer hingeschaut: Woher die Formel für „k aus n“ kommt', `<p>Wählt man 3 aus 5 Personen <b>mit</b> Reihenfolge, gibt es ${t('5\\cdot 4\\cdot 3=60')} Möglichkeiten. Dabei wird aber jede Dreiergruppe mehrfach gezählt – einmal für jede Anordnung ihrer Mitglieder, also ${t('3!=6')}-mal. Teilt man das heraus, bleiben die Gruppen ohne Reihenfolge:</p>${D('\\binom53=\\frac{5\\cdot 4\\cdot 3}{3!}=\\frac{60}{6}=10')}`],
    ['Beispiel 2: Ein Ausschuss', `<p>Aus 6 Frauen und 4 Männern werden 3 Personen ausgelost. Wie wahrscheinlich sind genau 2 Frauen?</p>${D('\\frac{\\binom62\\cdot\\binom41}{\\binom{10}{3}}=\\frac{15\\cdot 4}{120}=0{,}5')}<p>Im Zähler: 2 aus den 6 Frauen <b>und</b> 1 aus den 4 Männern – „und“ heißt malnehmen.</p>`],
    ['Beispiel 3: Passwörter', `<p>Vier Buchstaben aus 26. Mit Wiederholung: ${t('26^4=456\\,976')}. Ohne Wiederholung: ${t('26\\cdot 25\\cdot 24\\cdot 23=358\\,800')}. Jedes zusätzliche Zeichen macht das Passwort 26-mal so sicher – Länge schlägt Einfallsreichtum.</p>`],
    ['Beispiel 4: Gleiche Buchstaben', `<p>Wie viele verschiedene „Wörter“ lassen sich aus den Buchstaben von OTTO bilden? Vier Buchstaben ergäben ${t('4!=24')} Anordnungen. Weil die beiden O und die beiden T untereinander nicht unterscheidbar sind, wird jeweils durch ${t('2!')} geteilt:</p>${D('\\frac{4!}{2!\\cdot 2!}=6')}`],
    ['Sonderfälle', `<ul><li><b>Alle oder keinen:</b> ${t('\\binom n0=\\binom nn=1')}.</li><li><b>„Mindestens einer“:</b> oft leichter über das Gegenteil – alle Möglichkeiten minus die ohne.</li><li><b>Runder Tisch:</b> Es zählt nur, wer neben wem sitzt: ${t('(n-1)!')} statt ${t('n!')}.</li><li><b>Fakultäten wachsen rasant:</b> ${t('10!')} sind schon über 3,6 Millionen.</li></ul>`],
  ],
  's-zufall': [
    ['Genauer hingeschaut: Rechnen mit Erwartungswerten', `<p>Erwartungswerte verhalten sich angenehm: Verdoppelt man alle Gewinne, verdoppelt sich der Erwartungswert; zieht man einen festen Einsatz ab, sinkt er um genau diesen Betrag.</p>${D('E(a\\cdot X+b)=a\\cdot E(X)+b')}<p>Die Standardabweichung reagiert nur auf den Faktor: Sie wird ${t('|a|')}-mal so groß. Ein fester Zuschlag verschiebt alle Werte gemeinsam und ändert an der Streuung nichts.</p>`],
    ['Beispiel 2: Den fairen Einsatz finden', `<p>Bei einer Sechs werden 9 € ausgezahlt, sonst nichts. Bei welchem Einsatz ist das Spiel fair? Die erwartete Auszahlung ist ${t('9\\cdot\\tfrac16=1{,}50')} €. Genau so hoch muss der Einsatz sein – dann ist der erwartete Gewinn null.</p>`],
    ['Beispiel 3: Zwei Würfel', `<p>Ein Würfel zeigt im Mittel ${t('\\tfrac{1+2+3+4+5+6}{6}=3{,}5')}. Die Augensumme zweier Würfel hat den Erwartungswert ${t('3{,}5+3{,}5=7')}. Erwartungswerte darf man immer addieren – auch dann, wenn die Zufallsgrößen voneinander abhängen.</p>`],
    ['Beispiel 4: Unabhängigkeit nachrechnen', `<p>Ein Würfel wird einmal geworfen. ${t('A')}: gerade Zahl. ${t('B')}: mindestens 5.</p>${D('P(A)=\\tfrac12\\qquad P(B)=\\tfrac13\\qquad P(A\\cap B)=\\tfrac16')}<p>Beides zugleich trifft nur die 6. Und ${t('\\tfrac12\\cdot\\tfrac13=\\tfrac16')}: Die Ereignisse sind unabhängig – obwohl sie denselben Wurf betreffen.</p>`],
    ['Sonderfälle', `<ul><li><b>Erwartungswert ist kein möglicher Wert:</b> Kein Würfel zeigt 3,5.</li><li><b>Streuung null:</b> nur, wenn immer derselbe Wert herauskommt.</li><li><b>Große Grundmenge:</b> Zieht man wenige aus sehr vielen, ändert sich die Wahrscheinlichkeit kaum – die Binomialverteilung ist dann eine gute Näherung für „ohne Zurücklegen“.</li><li><b>Gleicher Erwartungswert, anderes Risiko:</b> Zwei Spiele können im Mittel dasselbe bringen und sich in der Streuung völlig unterscheiden.</li></ul>`],
  ],
  'g-grund': [
    ['Genauer hingeschaut: Der Satz gilt auch rückwärts', `<p>Stimmt in einem Dreieck ${t('a^2+b^2=c^2')}, dann <b>ist</b> es rechtwinklig. So lässt sich ohne Winkelmesser prüfen, ob eine Ecke genau 90° hat: Seiten 5, 12 und 13 ergeben ${t('25+144=169=13^2')} – rechtwinklig. Handwerker nutzen dafür das Dreieck mit den Seiten 3, 4 und 5.</p>`],
    ['Beispiel 2: Einen Winkel berechnen', `<p>Eine Rampe überwindet 1,2 m Höhe auf 8 m waagerechter Länge. Wie steil ist sie?</p>${D('\\tan\\alpha=\\frac{1{,}2}{8}=0{,}15\\quad\\Rightarrow\\quad\\alpha\\approx 8{,}5^\\circ')}<p>Gegeben waren Gegenkathete und Ankathete, also passt der Tangens. Den Winkel liefert die Umkehrtaste ${t('\\tan^{-1}')}.</p>`],
    ['Beispiel 3: Diagonale im Raum', `<p>Ein Quader ist 3 cm, 4 cm und 12 cm lang. Die Raumdiagonale bekommt man mit zweimal Pythagoras – oder gleich in einem Schritt:</p>${D('d=\\sqrt{3^2+4^2+12^2}=\\sqrt{169}=13')}<p>Genau so wird später die Länge eines Vektors berechnet.</p>`],
    ['Beispiel 4: Kegel', `<p>Radius 3 cm, Höhe 4 cm.</p>${D('V=\\tfrac13\\cdot\\pi\\cdot 3^2\\cdot 4=12\\pi\\approx 37{,}7')}<p>Die Mantellinie (vom Rand zur Spitze) ist die Hypotenuse aus Radius und Höhe: ${t('s=\\sqrt{9+16}=5')} cm.</p>`],
    ['Beispiel 5: Höhe im gleichseitigen Dreieck', `<p>Alle Seiten sind 6 cm lang. Die Höhe teilt das Dreieck in zwei rechtwinklige Dreiecke mit den Seiten 3 cm und 6 cm:</p>${D('h=\\sqrt{6^2-3^2}=\\sqrt{27}\\approx 5{,}20')}<p>Fläche: ${t('\\tfrac12\\cdot 6\\cdot 5{,}20\\approx 15{,}6')} cm². Dieser Trick – eine Höhe einzeichnen – macht aus fast jedem Dreieck zwei rechtwinklige.</p>`],
    ['Sonderfälle', `<ul><li><b>45°:</b> Beide Katheten sind gleich lang, ${t('\\tan 45^\\circ=1')}.</li><li><b>30° und 60°:</b> ${t('\\sin 30^\\circ=0{,}5')} – die Gegenkathete ist halb so lang wie die Hypotenuse.</li><li><b>Kein rechter Winkel:</b> Dann gelten Pythagoras und die einfachen Sinus-Formeln nicht. Abhilfe: eine Höhe einzeichnen, die das Dreieck in zwei rechtwinklige teilt.</li><li><b>Halbkugel, Kegelstumpf:</b> aus den Grundkörpern zusammensetzen oder abziehen.</li></ul>`],
  ],
  'g-vektor': [
    ['Genauer hingeschaut: Vektorketten', `<p>Geht man erst von ${t('A')} nach ${t('B')} und dann von ${t('B')} nach ${t('C')}, ist man insgesamt von ${t('A')} nach ${t('C')} gegangen:</p>${D('\\overrightarrow{AB}+\\overrightarrow{BC}=\\overrightarrow{AC}')}<p>Der <b>Gegenvektor</b> ${t('-\\vec a')} führt denselben Weg zurück. Ein geschlossener Weg ergibt den <b>Nullvektor</b>. Mit diesen drei Gedanken lassen sich fehlende Punkte in Figuren berechnen.</p>`],
    ['Beispiel 2: Der vierte Punkt eines Parallelogramms', `<p>${t('A(1\\mid 1\\mid 0)')}, ${t('B(4\\mid 2\\mid 1)')}, ${t('C(5\\mid 5\\mid 3)')}. Gesucht ist ${t('D')}, sodass ${t('ABCD')} ein Parallelogramm ist. Gegenüberliegende Seiten sind gleich, also führt von ${t('A')} nach ${t('D')} derselbe Vektor wie von ${t('B')} nach ${t('C')}:</p>${D('\\vec d=\\vec a+\\overrightarrow{BC}=\\begin{pmatrix}1\\\\1\\\\0\\end{pmatrix}+\\begin{pmatrix}1\\\\3\\\\2\\end{pmatrix}=\\begin{pmatrix}2\\\\4\\\\2\\end{pmatrix}')}<p>Probe: ${t('\\overrightarrow{AB}=(3\\mid 1\\mid 1)')} und ${t('\\overrightarrow{DC}=(3\\mid 1\\mid 1)')} – gleich.</p>`],
    ['Beispiel 3: Parallel oder nicht?', `<p>${t('\\vec a=(2\\mid -1\\mid 3)')} und ${t('\\vec b=(-4\\mid 2\\mid -6)')}: Jede Koordinate von ${t('\\vec b')} ist das ${t('(-2)')}-Fache. Die Vektoren sind parallel (und entgegengesetzt gerichtet).</p><p>${t('\\vec c=(4\\mid -2\\mid 5)')}: Die ersten beiden Koordinaten verlangen den Faktor 2, die dritte ${t('\\tfrac53')}. Kein gemeinsamer Faktor – nicht parallel.</p>`],
    ['Beispiel 4: Einen Punkt auf einer Strecke finden', `<p>Welcher Punkt ${t('T')} teilt die Strecke von ${t('A(1\\mid 2\\mid 3)')} nach ${t('B(4\\mid 0\\mid 5)')} so, dass er ein Drittel des Wegs von ${t('A')} entfernt liegt?</p>${D('\\vec t=\\vec a+\\tfrac13\\,\\overrightarrow{AB}=\\begin{pmatrix}1\\\\2\\\\3\\end{pmatrix}+\\tfrac13\\begin{pmatrix}3\\\\-2\\\\2\\end{pmatrix}')}<p>Ergebnis: ${t('T\\bigl(2\\mid\\tfrac43\\mid\\tfrac{11}{3}\\bigr)')}.</p>`],
    ['Sonderfälle', `<ul><li><b>Nullvektor:</b> Länge 0, keine Richtung.</li><li><b>Einheitsvektor:</b> Teilt man einen Vektor durch seine Länge, entsteht ein Vektor der Länge 1 mit derselben Richtung.</li><li><b>Drei Punkte auf einer Geraden:</b> genau dann, wenn ${t('\\overrightarrow{AB}')} und ${t('\\overrightarrow{AC}')} parallel sind.</li><li><b>Eine Koordinate null:</b> Der Faktor-Vergleich klappt nur, wenn beim anderen Vektor dieselbe Koordinate auch null ist.</li></ul>`],
  ],
  'g-skalar': [
    ['Genauer hingeschaut: Das Skalarprodukt als Schatten', `<p>Leuchtet man senkrecht auf ${t('\\vec a')}, wirft ${t('\\vec b')} einen Schatten auf ${t('\\vec a')}. Das Skalarprodukt ist die Länge von ${t('\\vec a')} mal die Länge dieses Schattens. Zeigt ${t('\\vec b')} in dieselbe Richtung, ist der Schatten lang; steht ${t('\\vec b')} senkrecht, schrumpft er auf null; zeigt ${t('\\vec b')} zurück, wird er negativ gezählt.</p>${D('\\vec a\\cdot\\vec a=|\\vec a|^2')}<p>Das Skalarprodukt eines Vektors mit sich selbst ist deshalb das Quadrat seiner Länge.</p>`],
    ['Beispiel 2: Einen Parameter passend wählen', `<p>Für welches ${t('k')} stehen ${t('\\vec a=(2\\mid k\\mid 1)')} und ${t('\\vec b=(1\\mid 2\\mid -4)')} senkrecht aufeinander?</p>${D('2\\cdot 1+k\\cdot 2+1\\cdot(-4)=2k-2=0\\quad\\Rightarrow\\quad k=1')}`],
    ['Beispiel 3: Ist das Dreieck rechtwinklig?', `<p>${t('A(1\\mid 0\\mid 0)')}, ${t('B(3\\mid 1\\mid 2)')}, ${t('C(0\\mid 2\\mid 1)')}. Die Seiten an der Ecke ${t('A')}: ${t('\\overrightarrow{AB}=(2\\mid 1\\mid 2)')} und ${t('\\overrightarrow{AC}=(-1\\mid 2\\mid 1)')}.</p>${D('\\overrightarrow{AB}\\cdot\\overrightarrow{AC}=-2+2+2=2')}<p>Nicht null – bei ${t('A')} ist kein rechter Winkel. Für eine vollständige Antwort müssen auch die Ecken ${t('B')} und ${t('C')} geprüft werden, jeweils mit den beiden Vektoren, die <b>von dieser Ecke weg</b> zeigen.</p>`],
    ['Beispiel 4: Ein Winkel im Dreieck', `<p>Winkel bei ${t('B')} im selben Dreieck: ${t('\\overrightarrow{BA}=(-2\\mid -1\\mid -2)')} und ${t('\\overrightarrow{BC}=(-3\\mid 1\\mid -1)')}.</p>${D('\\cos\\beta=\\frac{6-1+2}{3\\cdot\\sqrt{11}}\\approx 0{,}704\\quad\\Rightarrow\\quad\\beta\\approx 45{,}3^\\circ')}`],
    ['Sonderfälle', `<ul><li><b>Parallel:</b> ${t('\\cos\\varphi=1')} (gleiche Richtung) oder ${t('-1')} (entgegengesetzt).</li><li><b>Nullvektor:</b> Sein Skalarprodukt mit jedem Vektor ist null – als „senkrecht“ zählt das nicht.</li><li><b>Winkel zwischen Geraden:</b> höchstens 90°. Kommt mehr heraus, den Betrag des Skalarprodukts nehmen.</li><li><b>Winkel im Dreieck:</b> kann stumpf sein – hier <b>keinen</b> Betrag nehmen.</li></ul>`],
  ],
  'g-gerade': [
    ['Genauer hingeschaut: Eine Gerade, viele Gleichungen', `<p>Die Parameterform ist nicht eindeutig. Als Stützpunkt taugt <b>jeder</b> Punkt der Geraden, als Richtung jedes Vielfache des Richtungsvektors. Zwei verschieden aussehende Gleichungen können also dieselbe Gerade beschreiben – das zeigt erst die Prüfung: Richtungen parallel und ein Punkt der einen liegt auf der anderen.</p>`],
    ['Beispiel 2: Gerade durch zwei Punkte und Punktprobe', `<p>Durch ${t('A(1\\mid 2\\mid 0)')} und ${t('B(3\\mid 1\\mid 4)')}:</p>${D('g:\\ \\vec x=\\begin{pmatrix}1\\\\2\\\\0\\end{pmatrix}+t\\begin{pmatrix}2\\\\-1\\\\4\\end{pmatrix}')}<p>Liegt ${t('P(5\\mid 0\\mid 8)')} darauf? Erste Zeile: ${t('1+2t=5')}, also ${t('t=2')}. Zweite: ${t('2-2=0')}. Dritte: ${t('4\\cdot 2=8')}. Alle drei passen – ja.</p><p>Und ${t('Q(3\\mid 1\\mid 5)')}? Aus der ersten Zeile ${t('t=1')}, die dritte liefert dann 4 statt 5 – nein.</p>`],
    ['Beispiel 3: Windschief', `${D('g:\\ \\vec x=t\\begin{pmatrix}1\\\\0\\\\0\\end{pmatrix}\\qquad h:\\ \\vec x=\\begin{pmatrix}0\\\\1\\\\1\\end{pmatrix}+s\\begin{pmatrix}0\\\\1\\\\0\\end{pmatrix}')}<p>Die Richtungen sind nicht parallel. Gleichsetzen: ${t('t=0')}, ${t('0=1+s')} und ${t('0=1')}. Die dritte Gleichung ist nie erfüllt – es gibt keinen Schnittpunkt. Nicht parallel und kein Schnittpunkt: Die Geraden sind windschief, sie laufen in verschiedenen Höhen aneinander vorbei.</p>`],
    ['Beispiel 4: Bewegung im Raum', `<p>Eine Drohne startet in ${t('(2\\mid 1\\mid 3)')} und fliegt pro Minute um ${t('(3\\mid 4\\mid 0)')} weiter (Angaben in km). Nach ${t('t')} Minuten ist sie bei ${t('(2+3t\\mid 1+4t\\mid 3)')} – nach 10 Minuten also bei ${t('(32\\mid 41\\mid 3)')}.</p><p>Ihre Geschwindigkeit ist die Länge des Richtungsvektors: ${t('\\sqrt{9+16}=5')} km pro Minute. Die Höhe ändert sich nicht, weil die dritte Koordinate der Richtung null ist.</p>`],
    ['Sonderfälle', `<ul><li><b>Identisch:</b> Richtungen parallel <b>und</b> ein gemeinsamer Punkt.</li><li><b>Strecke statt Gerade:</b> Der Parameter läuft nur von 0 bis 1.</li><li><b>Spurpunkt:</b> Schnitt mit einer Koordinatenebene – eine Koordinate null setzen und ${t('t')} ausrechnen.</li><li><b>Parallel zu einer Achse:</b> Zwei Koordinaten des Richtungsvektors sind null.</li><li><b>Zwei Gleichungen passen, die dritte nicht:</b> kein Schnittpunkt – immer alle drei prüfen.</li></ul>`],
  ],
  'g-ebene': [
    ['Genauer hingeschaut: Warum eine einzige Gleichung genügt', `<p>${t('\\vec n\\cdot\\vec x')} misst, wie weit ein Punkt in Richtung des Normalenvektors liegt. Alle Punkte, für die dieser Wert gleich ist, liegen auf einer Fläche senkrecht zu ${t('\\vec n')} – einer Ebene. Ändert man nur die Zahl ${t('d')} auf der rechten Seite, verschiebt sich die Ebene parallel.</p>`],
    ['Beispiel 2: Gerade parallel zur Ebene', `<p>${t('E:\\ 2x_1-x_2+2x_3=6')} und ${t('g:\\ \\vec x=(1\\mid 0\\mid 0)+t\\,(1\\mid 2\\mid 0)')}.</p>${D('\\vec n\\cdot\\vec u=2\\cdot 1-1\\cdot 2+2\\cdot 0=0')}<p>Der Richtungsvektor steht senkrecht auf dem Normalenvektor: Die Gerade läuft parallel zur Ebene. Liegt sie vielleicht sogar darin? Punktprobe mit ${t('(1\\mid 0\\mid 0)')}: ${t('2\\ne 6')}. Also echt parallel, kein gemeinsamer Punkt.</p>`],
    ['Beispiel 3: Gerade in der Ebene', `<p>Dieselbe Richtung, aber Stützpunkt ${t('(3\\mid 0\\mid 0)')}: Die Punktprobe ergibt ${t('6=6')}. Jetzt liegt die <b>ganze</b> Gerade in der Ebene – es gibt unendlich viele gemeinsame Punkte. Beim Einsetzen fällt ${t('t')} heraus und es bleibt eine wahre Aussage.</p>`],
    ['Beispiel 4: Ebene aus Punkt und Normalenvektor', `<p>Gesucht ist die Ebene durch ${t('P(1\\mid 2\\mid 3)')} mit ${t('\\vec n=(2\\mid 0\\mid 1)')}. Die linke Seite steht sofort da, ${t('d')} kommt durch Einsetzen des Punktes:</p>${D('2x_1+x_3=d\\qquad d=2\\cdot 1+3=5')}<p>Also ${t('E:\\ 2x_1+x_3=5')}. Weil ${t('x_2')} fehlt, verläuft die Ebene parallel zur ${t('x_2')}-Achse.</p>`],
    ['Sonderfälle', `<ul><li><b>${t('x_3=4')}:</b> eine waagerechte Ebene in der Höhe 4, parallel zur ${t('x_1x_2')}-Ebene.</li><li><b>${t('d=0')}:</b> Die Ebene geht durch den Ursprung.</li><li><b>Vielfache:</b> ${t('4x_1-2x_2+4x_3=12')} ist dieselbe Ebene wie im Beispiel.</li><li><b>Beim Einsetzen bleibt eine falsche Aussage</b> (etwa ${t('2=6')}): Gerade und Ebene sind parallel.</li></ul>`],
  ],
  'g-mass': [
    ['Genauer hingeschaut: Woher die Abstandsformel kommt', `<p>Teilt man den Normalenvektor durch seine Länge, hat er die Länge 1. Das Skalarprodukt mit diesem Einheitsvektor misst dann direkt, wie weit ein Punkt in Richtung der Senkrechten liegt. Die Formel vergleicht diesen Wert für den Punkt ${t('P')} mit dem Wert für die Ebene – der Unterschied ist der Abstand. Der Betrag sorgt dafür, dass es egal ist, auf welcher Seite ${t('P')} liegt.</p>`],
    ['Beispiel 2: Abstand zweier paralleler Ebenen', `<p>${t('E_1:\\ 2x_1-x_2+2x_3=6')} und ${t('E_2:\\ 2x_1-x_2+2x_3=15')}. Ein Punkt von ${t('E_1')} ist ${t('(3\\mid 0\\mid 0)')}. Sein Abstand zu ${t('E_2')}:</p>${D('\\frac{|6-15|}{3}=3')}<p>Bei gleichen linken Seiten geht es also noch kürzer: Unterschied der rechten Seiten, geteilt durch die Länge des Normalenvektors.</p>`],
    ['Beispiel 3: Winkel zwischen Gerade und Ebene', `<p>Richtungsvektor ${t('\\vec u=(1\\mid 2\\mid 2)')}, Normalenvektor ${t('\\vec n=(2\\mid -1\\mid 2)')}.</p>${D('\\sin\\varphi=\\frac{|2-2+4|}{3\\cdot 3}=\\frac49\\quad\\Rightarrow\\quad\\varphi\\approx 26{,}4^\\circ')}<p>Mit dem Kosinus käme der Winkel zur Senkrechten heraus (63,6°) – die beiden ergänzen sich zu 90°.</p>`],
    ['Beispiel 4: Winkel zwischen zwei Ebenen', `<p>${t('\\vec n_1=(1\\mid 0\\mid 0)')} und ${t('\\vec n_2=(1\\mid 1\\mid 0)')}.</p>${D('\\cos\\varphi=\\frac{1}{1\\cdot\\sqrt 2}\\quad\\Rightarrow\\quad\\varphi=45^\\circ')}<p>Der Winkel zwischen zwei Ebenen ist der Winkel zwischen ihren Normalenvektoren.</p>`],
    ['Sonderfälle', `<ul><li><b>Abstand null:</b> Der Punkt liegt in der Ebene.</li><li><b>Gerade parallel zur Ebene:</b> Jeder Punkt der Geraden hat denselben Abstand – einen beliebigen einsetzen.</li><li><b>Gerade schneidet die Ebene:</b> Der Abstand ist null.</li><li><b>Senkrecht:</b> Bei Gerade und Ebene ist dann ${t('\\vec u')} ein Vielfaches von ${t('\\vec n')}; bei zwei Ebenen ist ${t('\\vec n_1\\cdot\\vec n_2=0')}.</li><li><b>Schnittwinkel:</b> immer höchstens 90° – deshalb der Betrag.</li></ul>`],
  ],
  'g-kugel': [
    ['Genauer hingeschaut: Die Kugelgleichung ist die Abstandsformel', `<p>Für den Abstand ${t('d')} eines Punktes ${t('X')} vom Mittelpunkt gilt nach Pythagoras:</p>${D('\\begin{aligned}d^2&=(x_1-m_1)^2+(x_2-m_2)^2\\\\&\\quad+(x_3-m_3)^2\\end{aligned}')}<p>Soll der Abstand gleich ${t('r')} sein, setzt man ${t('d^2=r^2')} – schon steht die Kugelgleichung da. Mehr steckt nicht dahinter – wer die Länge eines Vektors berechnen kann, kennt die Kugel schon.</p>`],
    ['Beispiel 2: Gerade trifft Kugel', `<p>Kugel um den Ursprung mit ${t('r=3')}: ${t('x_1^2+x_2^2+x_3^2=9')}. Gerade ${t('g:\\ \\vec x=(3\\mid 0\\mid 0)+t\\,(-1\\mid 1\\mid 0)')}. Einsetzen:</p>${D('(3-t)^2+t^2=9\\quad\\Rightarrow\\quad 2t^2-6t=0')}<p>Also ${t('t=0')} oder ${t('t=3')}: Die Gerade durchstößt die Kugel in ${t('S_1(3\\mid 0\\mid 0)')} und ${t('S_2(0\\mid 3\\mid 0)')}.</p>`],
    ['Beispiel 3: Tangentialebene', `<p>${t('B(1\\mid 2\\mid 2)')} liegt auf dieser Kugel, denn ${t('1+4+4=9')}. Die Ebene, die die Kugel in ${t('B')} berührt, steht senkrecht auf dem Radius. Der Vektor vom Mittelpunkt zu ${t('B')} ist also ihr Normalenvektor:</p>${D('E:\\ x_1+2x_2+2x_3=9')}<p>Die rechte Seite entsteht durch Einsetzen von ${t('B')}.</p>`],
    ['Beispiel 4: Schnittkreis', `<p>Kugel um den Ursprung mit ${t('r=5')}, Ebene ${t('x_3=3')}. Der Mittelpunkt ist 3 von der Ebene entfernt.</p>${D('r_{\\text{Kreis}}=\\sqrt{5^2-3^2}=4')}<p>Der Schnittkreis hat den Radius 4 und den Mittelpunkt ${t('(0\\mid 0\\mid 3)')} – das ist der Lotfußpunkt des Kugelmittelpunkts auf der Ebene.</p>`],
    ['Sonderfälle', `<ul><li><b>Gerade und Kugel:</b> Die quadratische Gleichung hat zwei Lösungen (Sekante), eine (Tangente) oder keine (Passante).</li><li><b>Zwei Kugeln:</b> Sie berühren sich von außen, wenn der Abstand der Mittelpunkte gleich ${t('r_1+r_2')} ist.</li><li><b>Ausmultiplizierte Gleichung:</b> Die quadratische Ergänzung holt Mittelpunkt und Radius zurück, etwa so:${D('x_1^2-4x_1=(x_1-2)^2-4')}</li><li><b>Ebene durch den Mittelpunkt:</b> Der Schnittkreis ist ein Großkreis mit Radius ${t('r')}.</li></ul>`],
  ],
  'g-ebene2': [
    ['Genauer hingeschaut: Normalenvektor ohne Kreuzprodukt', `<p>Wer das Kreuzprodukt nicht benutzen möchte, löst zwei Gleichungen: Der Normalenvektor muss auf beiden Spannvektoren senkrecht stehen. Für ${t('\\vec u=(1\\mid 0\\mid 2)')} und ${t('\\vec v=(0\\mid 1\\mid -1)')}:</p>${D('n_1+2n_3=0\\qquad n_2-n_3=0')}<p>Zwei Gleichungen, drei Unbekannte – eine darf man frei wählen. Mit ${t('n_3=1')} folgt ${t('n_1=-2')} und ${t('n_2=1')}: ${t('\\vec n=(-2\\mid 1\\mid 1)')}. Jedes Vielfache davon ist genauso richtig.</p>`],
    ['Beispiel 2: Von der Koordinatenform zurück zur Parameterform', `<p>${t('E:\\ x_1+2x_2+2x_3=6')}. Drei Punkte der Ebene findet man am schnellsten über die Spurpunkte: ${t('(6\\mid 0\\mid 0)')}, ${t('(0\\mid 3\\mid 0)')}, ${t('(0\\mid 0\\mid 3)')}.</p>${D('E:\\ \\vec x=\\begin{pmatrix}6\\\\0\\\\0\\end{pmatrix}+r\\begin{pmatrix}-6\\\\3\\\\0\\end{pmatrix}+s\\begin{pmatrix}-6\\\\0\\\\3\\end{pmatrix}')}`],
    ['Beispiel 3: Punktprobe in der Parameterform', `<p>Liegt ${t('P(-1\\mid 2\\mid 3)')} in dieser Ebene?</p>${D('E:\\ \\vec x=\\begin{pmatrix}1\\\\0\\\\0\\end{pmatrix}+r\\begin{pmatrix}-1\\\\2\\\\0\\end{pmatrix}+s\\begin{pmatrix}-1\\\\0\\\\3\\end{pmatrix}')}<p>Zweite Zeile: ${t('2r=2')}, also ${t('r=1')}. Dritte Zeile: ${t('3s=3')}, also ${t('s=1')}. Erste Zeile zur Kontrolle: ${t('1-1-1=-1')}. Passt – der Punkt liegt in der Ebene.</p><p>In der Koordinatenform ${t('6x_1+3x_2+2x_3=6')} wäre das eine einzige Zeile: ${t('-6+6+6=6')}. Deshalb lohnt sich das Umwandeln.</p>`],
    ['Sonderfälle', `<ul><li><b>Spannvektoren parallel:</b> Sie spannen keine Ebene auf, nur eine Gerade. Das Kreuzprodukt ist dann der Nullvektor.</li><li><b>Drei Punkte auf einer Geraden:</b> legen keine Ebene fest.</li><li><b>Ebene durch den Ursprung:</b> Alle drei Spurpunkte fallen im Ursprung zusammen – ein Spurdreieck gibt es nicht.</li><li><b>Parallel zu einer Achse:</b> Auf dieser Achse fehlt der Spurpunkt; gezeichnet wird mit den beiden anderen.</li></ul>`],
  ],
  'a-umkehr': [
    ['Genauer hingeschaut: Warum die Graphen Spiegelbilder sind', `<p>Liegt der Punkt ${t('(a\\mid b)')} auf dem Graphen von ${t('f')}, dann gilt ${t('f(a)=b')} – und damit ${t('f^{-1}(b)=a')}. Auf dem Graphen der Umkehrfunktion liegt also ${t('(b\\mid a)')}: Die Koordinaten sind vertauscht. Genau das bewirkt die Spiegelung an der Winkelhalbierenden ${t('y=x')}.</p><p>Daraus folgt auch: Die Steigungen an zusammengehörenden Punkten sind Kehrwerte voneinander.</p>`],
    ['Beispiel 2: Umkehrfunktion einer e-Funktion', `<p>${t('f(x)=2e^{3x}')}. Auflösen nach ${t('x')}:</p>${D('y=2e^{3x}\\ \\Rightarrow\\ \\dfrac y2=e^{3x}\\ \\Rightarrow\\ 3x=\\ln\\left(\\dfrac y2\\right)\\ \\Rightarrow\\ x=\\dfrac13\\ln\\left(\\dfrac y2\\right)')}<p>Also ${t('f^{-1}(x)=\\tfrac13\\ln\\left(\\tfrac x2\\right)')}, definiert für ${t('x>0')} – denn ${t('f')} nimmt nur positive Werte an.</p>`],
    ['Beispiel 3: Verkettete Wurzel ableiten', `<p>${t('f(x)=\\sqrt{4x+1}')}. Außen steht die Wurzel, innen ${t('4x+1')}.</p>${D("f'(x)=\\dfrac{1}{2\\sqrt{4x+1}}\\cdot 4=\\dfrac{2}{\\sqrt{4x+1}}")}<p>An der Stelle ${t('x=2')}: ${t("f'(2)=\\tfrac23")}. Die Funktion ist für ${t('x\\ge -\\tfrac14')} definiert, die Ableitung erst für ${t('x>-\\tfrac14')}.</p>`],
    ['Sonderfälle', `<ul><li><b>Am Rand des Definitionsbereichs:</b> ${t('\\sqrt x')} ist bei ${t('x=0')} definiert, aber nicht ableitbar – die Tangente wäre senkrecht.</li><li><b>Selbstumkehrend:</b> ${t('f(x)=\\tfrac1x')} und ${t('f(x)=-x+c')} sind ihre eigene Umkehrfunktion.</li><li><b>Nicht umkehrbar:</b> Sinus und Parabel sind es nur auf einem eingeschränkten Bereich.</li><li><b>Ungerade Wurzeln:</b> ${t('\\sqrt[3]{x}')} ist auch für negative ${t('x')} erklärt.</li></ul>`],
  ],
  'a-numerik': [
    ['Genauer hingeschaut: Woher die Newton-Formel kommt', `<p>Die Tangente an der Stelle ${t('x_n')} hat die Gleichung ${t("y=f'(x_n)\\cdot(x-x_n)+f(x_n)")}. Setzt man ${t('y=0')} und löst nach ${t('x')} auf, steht die Formel da:</p>${D("0=f'(x_n)(x-x_n)+f(x_n)\\ \\Rightarrow\\ x=x_n-\\dfrac{f(x_n)}{f'(x_n)}")}<p>Das Verfahren ist also nichts anderes als „Tangente statt Kurve“, immer wieder.</p>`],
    ['Beispiel 2: Integralfunktion ohne Integralzeichen', `<p>${t('J_1(x)=\\displaystyle\\int_1^x(2t+3)\\,dt')}. Stammfunktion: ${t('F(t)=t^2+3t')}, ${t('F(1)=4')}.</p>${D('J_1(x)=x^2+3x-4')}<p>Probe: ${t('J_1(1)=0')} und ${t("J_1'(x)=2x+3")}. Beides stimmt. Die Nullstellen ${t('x=1')} und ${t('x=-4')} sind die Stellen, an denen sich positive und negative Flächenanteile ausgleichen.</p>`],
    ['Beispiel 3: Ortskurve der Tiefpunkte', `<p>${t('f_k(x)=x^3-3k^2x')} mit ${t('k>0')}. Aus ${t("f_k'(x)=3x^2-3k^2=0")} folgt ${t('x=\\pm k')}; der Tiefpunkt liegt bei ${t('x=k')}.</p>${D('y=k^3-3k^3=-2k^3\\ \\Rightarrow\\ y=-2x^3\\quad(x>0)')}<p>Die Einschränkung ${t('x>0')} gehört dazu, weil ${t('k>0')} vorausgesetzt war.</p>`],
    ['Sonderfälle', `<ul><li><b>Waagerechte Tangente:</b> Bei ${t("f'(x_n)=0")} gibt es keinen nächsten Wert – anderen Startwert wählen.</li><li><b>Schlechter Startwert:</b> Das Verfahren kann zu einer anderen Nullstelle springen oder hin und her pendeln.</li><li><b>Verschiedene untere Grenzen:</b> ${t('J_a')} und ${t('J_b')} unterscheiden sich nur um eine Konstante.</li><li><b>Nicht jede Stammfunktion ist Integralfunktion:</b> ${t('F(x)=x^2+1')} hat keine Nullstelle.</li></ul>`],
  ],
  's-test2': [
    ['Genauer hingeschaut: Warum 1,96?', `<p>Für große ${t('n')} sieht das Histogramm einer Binomialverteilung aus wie eine Glockenkurve. Bei dieser liegen 95 % der Fläche zwischen ${t('\\mu-1{,}96\\sigma')} und ${t('\\mu+1{,}96\\sigma')}; außerhalb bleiben je 2,5 % auf jeder Seite. Für 99 % braucht man ${t('2{,}58\\sigma')}.</p><p>Die Faustregel gilt gut, wenn ${t('\\sigma>3')} ist (Laplace-Bedingung).</p>`],
    ['Beispiel 2: Gleichverteilung', `<p>Eine S-Bahn fährt alle 10 Minuten. Wer zufällig zur Haltestelle kommt, wartet ${t('X')} Minuten, gleichverteilt auf ${t('[0;\\ 10]')}. Die Dichte hat die Höhe ${t('\\tfrac1{10}')}.</p>${D('P(2\\le X\\le 5)=3\\cdot\\dfrac{1}{10}=0{,}3')}<p>Der Erwartungswert liegt in der Mitte: 5 Minuten.</p>`],
    ['Beispiel 3: n rückwärts aus dem Erwartungswert', `<p>Bei einem Gewinnspiel gewinnt jedes achte Los, also ${t('p=0{,}125')}. Wie viele Lose braucht man, damit im Mittel 20 Gewinne zu erwarten sind?</p>${D('\\mu=n\\cdot p\\ \\Rightarrow\\ n=\\dfrac{20}{0{,}125}=160')}<p>Die Standardabweichung ist dann ${t('\\sigma=\\sqrt{160\\cdot 0{,}125\\cdot 0{,}875}\\approx 4{,}18')}.</p>`],
    ['Beispiel 4: Mit der kumulierten Tabelle rechnen', `<p>${t('n=20')}, ${t('p=0{,}25')}. Aus der Tabelle: ${t('P(X\\le 3)=0{,}2252')}, ${t('P(X\\le 4)=0{,}4148')}, ${t('P(X\\le 7)=0{,}8982')}.</p>${D('P(X=4)=0{,}4148-0{,}2252=0{,}1896')}${D('P(X\\ge 4)=1-0{,}2252=0{,}7748\\qquad P(4\\le X\\le 7)=0{,}8982-0{,}2252=0{,}6730')}<p>Der häufigste Fehler: bei „mindestens 4“ den Wert für ${t('k=4')} statt für ${t('k=3')} abzuziehen.</p>`],
    ['Sonderfälle', `<ul><li><b>Erwartungswert nicht ganzzahlig:</b> Die höchste Säule steht bei der größten ganzen Zahl unter ${t('(n+1)\\cdot p')}.</li><li><b>Zwei gleich hohe Säulen:</b> Ist ${t('(n+1)\\cdot p')} ganzzahlig, gibt es zwei wahrscheinlichste Trefferzahlen.</li><li><b>Unvereinbare Ereignisse:</b> Bei ${t('A\\cap B=\\{\\,\\}')} gilt einfach ${t('P(A\\cup B)=P(A)+P(B)')}.</li><li><b>Dichte größer als 1:</b> Erlaubt – nur die Fläche muss 1 sein.</li></ul>`],
  ],
  'g-abstand2': [
    ['Genauer hingeschaut: Warum die Hesse-Form den Abstand liefert', `<p>Das Skalarprodukt ${t('\\vec n\\cdot\\overrightarrow{AP}')} misst, wie weit ${t('P')} von einem Ebenenpunkt ${t('A')} in Richtung des Normalenvektors entfernt ist – allerdings gestreckt um die Länge von ${t('\\vec n')}. Teilt man durch ${t('|\\vec n|')}, bleibt die echte Länge übrig.</p>${D('d=\\dfrac{|\\vec n\\cdot(\\vec p-\\vec a)|}{|\\vec n|}=\\dfrac{|\\vec n\\cdot\\vec p-d|}{|\\vec n|}')}`],
    ['Beispiel 2: Schnittgerade bestimmen', `<p>${t('E_1:\\ x_1+x_2+x_3=6')} und ${t('E_2:\\ x_1-x_2=0')}. Richtung: ${t('\\vec n_1\\times\\vec n_2=(1\\mid 1\\mid -2)')}.</p><p>Stützpunkt mit ${t('x_3=0')}: Aus ${t('x_1=x_2')} und ${t('x_1+x_2=6')} folgt ${t('(3\\mid 3\\mid 0)')}.</p>${D('g:\\ \\vec x=\\begin{pmatrix}3\\\\3\\\\0\\end{pmatrix}+t\\begin{pmatrix}1\\\\1\\\\-2\\end{pmatrix}')}`],
    ['Beispiel 3: Abstand windschiefer Geraden', `<p>${t('g:\\ \\vec x=(0\\mid 0\\mid 0)+r\\,(1\\mid 0\\mid 2)')} und ${t('h:\\ \\vec x=(3\\mid 3\\mid 0)+s\\,(0\\mid 1\\mid 2)')}. Normalenvektor: ${t('\\vec n=(-2\\mid -2\\mid 1)')} mit der Länge 3.</p>${D('d=\\dfrac{|(3\\mid 3\\mid 0)\\cdot(-2\\mid -2\\mid 1)|}{3}=\\dfrac{12}{3}=4')}<p>Die beiden Geraden kommen sich nie näher als 4 Längeneinheiten.</p>`],
    ['Sonderfälle', `<ul><li><b>Parallele Ebenen:</b> Keine Schnittgerade – das Kreuzprodukt der Normalenvektoren ist der Nullvektor. Der Abstand ist ${t('\\tfrac{|d_2-d_1|}{|\\vec n|}')}.</li><li><b>Punkt in der Ebene:</b> Abstand 0, Spiegelpunkt gleich dem Punkt selbst.</li><li><b>Sich schneidende Geraden:</b> Die Formel für windschiefe Geraden liefert dann 0.</li><li><b>Bewegung:</b> Zwei Bahnen können sich kreuzen, ohne dass die Fahrzeuge zusammenstoßen – es zählt derselbe Zeitpunkt.</li></ul>`],
  ],
};
